import {showReward} from './reward-panel.js';
import {money} from './economy.js';
import {defaultAlerts,emptySound} from './alerts.js';
import {seed,validate,uid,today,localDateTime,missionDefaults,xpFor,progress,level,complete,purchase,themes,defaultAppearance,resistanceLabels,slipLabels,drainLabels,reminderTimes,alarmPlan,checkSchedule,vitals,coinsFor,defaultCoins,pruneCalendarHistory} from './engine.js';
import {sprite,hairNames,clothesNames,itemNames} from './character.js';
import {icons,iconSvg} from './icons.js';
import {outfitParts,itemParts,outfitPalette,itemPalette,eyeNames,faceNames,mouthNames,browNames,beardNames} from './customization.js';
import {occurrenceTiming,effectiveDeadline,validateSlots,slotDates} from './timing.js';
import {radarSvg} from './radar.js';
import {defaultPalette,pickColor,tagPath,itemTags,hasTag,eventColor,readableColor,deleteTag,calendarExportQuests,prepareCalendarTags,validColor,manualTags,lockedTag,isSystemTag,tagOwners,pairEntityTag,syncEntityName,linkedEntities,matchesOrganization} from './tags.js';
import {defaultRecurrence,defaultCalendar,recurrenceFor,recurrenceLabel,localDay} from './schedule.js';
import {calendarEvents,exportICS,importICS} from './calendar.js';
import {soundCategories,soundNames,defaultSounds,readAudio,previewSound,rewardSounds,unlockAudio} from './sound.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const native=!!window.DaemonNative,fmt=v=>new Date(v).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
let batteryInfo=null,batteryReadAt=0;
let pendingAlertSound=null;
let loadError=false,state;try{const stored=localStorage.getItem('daemon-deck');state=stored?validate(JSON.parse(stored)):seed();}catch{state=seed();loadError=true;}
let selectedSkill='',newSkillParent='',characterDraft=null,newQuestKind='main',newQuestDate='',calendarDate=new Date(),calendarView='month',calendarKind='all',calendarTag='all',calendarQuery='',calendarShowCompleted=true,calendarEntries=[],calendarSearchOpen=false;
let page='deck',filter='today',query='',sort='recent',category='all',draft=null,dirty=false,editingImage='',nativeStatus={},alarmError='';
const orgFilters={missions:{attributes:[],skills:[],tags:[],match:'any'},calendar:{attributes:[],skills:[],tags:[],match:'any'}},orgOpen=new Set();
const nav=[['deck','▦','Deck'],['missions','⚑','Missions'],['calendar','▦','Calendar'],['skills','◈','Attributes'],['rewards','€$','Exchange'],['journal','▤','Logs'],['settings','⚙','Config']];
function toast(message){const modal=$('#editor');if(modal?.open){let local=modal.querySelector('#editor-error,[data-dialog-status]');if(!local){local=document.createElement('p');local.className='form-error';local.dataset.dialogStatus='';local.setAttribute('role','alert');modal.append(local);}local.textContent=message;}$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function syncAlarms(){try{if(native){const result=JSON.parse(window.DaemonNative.setAlarms(JSON.stringify(alarmPlan(state))));alarmError=result.error||'';if(alarmError)toast(alarmError);}}catch{alarmError='Alarm scheduling failed. Check Config → Alarm access.';toast(alarmError);}}
function persist(){try{state=validate(state);pruneCalendarHistory(state);localStorage.setItem('daemon-deck',JSON.stringify(state));loadError=false;syncAlarms();return true;}catch(e){toast(e.name==='QuotaExceededError'?'Storage full. Export a backup and remove large images.':e.message);return false;}}
function mutate(fn){const previous=structuredClone(state);try{fn();if(!persist()){state=previous;return false;}return true;}catch(e){state=previous;toast(e.message);return false;}}
function applyAppearance(a){const root=document.documentElement;for(const k of ['accent','secondary','bg','panel','text'])root.style.setProperty('--'+k,a[k]);root.style.setProperty('--text-scale',(a.textScale||100)/100);root.style.setProperty('--ui-scale',(a.uiScale||100)/100);root.dataset.subtheme=a.subtheme;root.dataset.scanlines=a.scanlines;document.body.classList.toggle('compact',a.compact);}
function go(next){if(page==='settings'&&dirty){if(!confirm('Save these settings? Cancel to keep editing.'))return;if(!saveAppearance())return;}page=next;selectedSkill='';filter='today';query='';category='all';if(next==='settings')draft=structuredClone(state.settings.appearance);render();scrollTo(0,0);}
function saveAppearance(){if(!draft)return true;if(!mutate(()=>state.settings.appearance=structuredClone(draft)))return false;dirty=false;toast('Appearance saved.');return true;}
function art(x){return x.image?`<img class="item-art" src="${esc(x.image)}" alt="">`:`<span class="item-art">${iconSvg(x.icon)||esc(x.icon||'⌁')}</span>`;}
function xpBar(x){const p=progress(x);return `<div class="bar" role="meter" aria-label="Level XP" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.current}"><i style="width:${p.current/p.total*100}%"></i></div>`;}
function heading(code,title,desc,action=''){return `<div class="section-heading"><div><span class="eyebrow">${code}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function permissionState(){if(!native)return {};try{return JSON.parse(window.DaemonNative.getPermissionState());}catch{return {notifications:false,exact:false,battery:false,error:'Unable to read Android permissions.'};}}
function permissionPanel(gate=false){const s=permissionState();return `<section class="panel permission-panel"><div class="panel-title"><h2>${gate?'ALARM ACCESS REQUIRED':'Alarm access'}</h2><span class="chip">ANDROID</span></div><p>Enable notifications, exact alarms, and unrestricted battery access before entering the deck.</p>${[['notifications','Notifications','Display and sound mission alerts.'],['exact','Alarms & reminders','Schedule exact alarms while the app is closed.'],['battery','Unrestricted battery','Allow scheduling outside normal battery optimization.']].map(([k,name,desc])=>`<div class="permission-row"><span class="status-led ${s[k]?'ok':''}"></span><div><b>${name}</b><small>${desc}</small></div><button class="${s[k]?'text-button':'primary'}" data-permission="${k}">${s[k]?'Settings':'Enable'}</button></div>`).join('')}<p class="fine-print">Android retains final control: Do Not Disturb, disabled notification channels, force-stop, and manufacturer battery rules can silence or delay alarms. No app can bypass these restrictions.</p>${gate?'<button class="secondary" data-action="refresh-permissions">Recheck access ↻</button>':'<button class="secondary" data-action="test-alarm">Send test alert</button>'}${s.error?`<p role="alert">${esc(s.error)}</p>`:''}${alarmError?`<p role="alert">${esc(alarmError)}</p>`:''}</section>`;}
function render(){document.body.classList.toggle('focus-mode',state.settings.attention.focus);document.body.classList.toggle('reduce-motion',state.settings.attention.reducedMotion);applyAppearance(page==='settings'&&draft?draft:state.settings.appearance);nativeStatus=permissionState();if(native&&(!nativeStatus.notifications||!nativeStatus.exact||!nativeStatus.battery)){$('#app').innerHTML=`<main class="setup"><div class="setup-brand">DÆMON<span>// DECK</span></div>${permissionPanel(true)}<small class="eyebrow">LOCAL SYSTEM · NO ACCOUNT REQUIRED</small></main>`;bind();updateClock();return;}
 const p=progress(state.profile.xp);$('#app').innerHTML=`<aside class="sidebar"><a href="#deck" class="brand" data-go="deck"><img src="icon.svg" alt="">DÆMON<span>DECK</span></a><div class="workspace-label">PERSONAL OPERATING SYSTEM</div><nav>${nav.map(([k,icon,title])=>`<button class="nav-item ${page===k?'active':''}" data-go="${k}"><span>${icon}</span>${title}${k==='missions'?`<small>${state.missions.filter(m=>m.status==='active').length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="system-state"><i></i> LOCAL STORAGE <span>ONLINE</span></div><button class="profile-mini" data-action="profile"><div class="mini-sprite">${characterView()}</div><div><b>${esc(state.profile.name)}</b><small>LVL ${p.level} / ${esc(state.profile.title)}</small></div><span>↗</span></button><small class="build-id">DÆMON OS / 1.0.0 · OVERHAUL</small></div></aside><main><header class="topbar"><div class="breadcrumb">DÆMON OS <span>/</span> <b>${nav.find(n=>n[0]===page)[2].toUpperCase()}</b></div><div class="top-actions"><time class="cyber-clock" aria-label="Local date and time"></time><span class="connection"><i></i> LOCAL</span><div class="header-telemetry"><span class="battery-status" hidden aria-label="Battery status"></span><span class="coin">${money(state.profile.coins)}</span></div><button class="avatar-button" data-action="profile" aria-label="Edit operator">${state.profile.name[0]?esc(state.profile.name[0].toUpperCase()):'Ø'}</button></div></header><div class="main-content">${loadError?'<div class="error-banner">Stored data could not be loaded. <button class="text-button" data-action="export-raw">Download original data before editing</button></div>':''}${({deck,missions,calendar:calendarPage,skills,rewards,journal,settings})[page]()}</div><footer><span>DÆMON DECK / 02</span><span>LOCAL FIRST. OPERATOR CONTROLLED.</span><span>EXTENSIVE_OVERHAUL</span></footer></main><nav class="mobile-nav">${nav.filter(n=>n[0]!=='journal').map(([k,icon,title])=>`<button data-go="${k}" class="${page===k?'active':''}">${icon}<small>${title}</small></button>`).join('')}</nav>`;bind();updateClock();const strip=$('.mobile-nav'),active=strip?.querySelector('.active');if(active)strip.scrollLeft=active.offsetLeft-(strip.clientWidth-active.offsetWidth)/2;}
function characterView(c=state.profile.character,image=state.profile.avatar){return `<span class="avatar-scale" style="--avatar-scale:${(c.scale||100)/100}">`+( c.mode==='image'&&image?`<img class="operator-image" src="${esc(image)}" alt="Custom operator">`:sprite(c))+'</span>';}
function deck(){const p=progress(state.profile.xp),completed=state.history.filter(h=>h.type==='complete'),active=state.missions.filter(m=>m.status==='active'),overdue=active.filter(m=>Date.parse(effectiveDeadline(state,m))<Date.now()).length;return `<div class="deck-heading"><div><span class="eyebrow">// OPERATOR TERMINAL</span><h1>${esc(state.profile.name)}<span class="cursor">_</span></h1></div><span class="chip">PROFILE / LOCAL</span></div><section class="operator-console"><div class="console-top"><span><i class="status-led ok"></i> OPERATOR_LINK.ACTIVE</span><span>SYS / ${String(p.level).padStart(2,'0')}</span></div><div class="operator-grid"><div class="operator-info"><span class="eyebrow">IDENTITY</span><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.title)}</p><div class="level-display"><span>LVL</span><b>${String(p.level).padStart(2,'0')}</b><small>${state.profile.xp} TOTAL XP</small></div>${xpBar(state.profile.xp)}<small>${p.current} / ${p.total} XP → LVL ${p.level+1}</small><button class="secondary" data-action="profile">Edit operator ↗</button></div><div class="character-screen" ${state.settings.cover?`style="background-image:linear-gradient(#07122177,#07122177),url('${esc(state.settings.cover)}')"`:''}><span class="screen-coordinate">X:024 / Y:032</span><div class="pixel-stage">${characterView()}</div><div class="floor-grid"></div><div class="character-controls"><button class="secondary" data-action="profile">EDIT OPERATOR ↗</button></div></div><div class="operator-telemetry"><span class="eyebrow">TELEMETRY</span>${vitalsPanel()}<div class="telemetry"><span>ACTIVE</span><b>${String(active.length).padStart(2,'0')}</b></div><div class="telemetry"><span>OVERDUE</span><b class="${overdue?'warning':''}">${String(overdue).padStart(2,'0')}</b></div></div></div><div class="console-bottom"><span>CHARACTER_ENGINE / 24 × 32 PX</span><span>LOCAL SAVE <i>●</i></span></div></section><section class="analytics"><div class="panel-title"><h2>Operator analytics</h2><span class="eyebrow">LIVE / ON DEVICE</span></div><div class="stat-grid"><div class="stat"><small>MISSIONS CLEARED</small><b>${completed.length.toString().padStart(2,'0')}</b><span>${completed.filter(h=>new Date(h.at).toDateString()===new Date().toDateString()).length} today</span></div><div class="stat"><small>EXPERIENCE</small><b>${state.profile.xp}</b><span>${completed.reduce((n,h)=>n+(h.xp||0),0)} XP from logged completions</span></div><div class="stat"><small>EURODOLLARS</small><b>${state.profile.coins}</b><span>${state.rewards.reduce((n,r)=>n+r.inventory,0)} items in inventory</span></div><div class="stat activity-stat"><small>ACTIVITY / LAST 7 DAYS</small>${activityChart(completed)}</div></div></section><section class="panel deck-skill-web"><div class="panel-title"><h2>Attribute web</h2><span class="chip">ATTRIBUTES / XP</span></div><button class="radar-trigger" data-action="radar" aria-label="Expand Attribute web to all Attributes and Skills">${radarSvg(state.skills.filter(s=>!s.parentId))}<span class="radar-expand">TAP TO EXPAND / ATTRIBUTES + SKILLS ↗</span></button><div class="radar-legend">${state.skills.filter(s=>!s.parentId).map(s=>`<span><b>${esc(s.title)}</b><small>${s.xp} XP</small></span>`).join('')}</div></section>`;}
function activityChart(history){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return {date:d,count:history.filter(h=>new Date(h.at).toDateString()===d.toDateString()).length};}),max=Math.max(1,...days.map(d=>d.count));return `<div class="activity-chart" role="img" aria-label="${esc(days.map(d=>`${d.date.toLocaleDateString()}: ${d.count} completions`).join('; '))}">${days.map(d=>`<div title="${d.count} cleared"><b>${d.count}</b><i style="height:${Math.max(2,d.count/max*44)}px"></i><small>${d.date.toLocaleDateString([],{weekday:'narrow'})}</small></div>`).join('')}</div>`;}
function tabs(items){return `<div class="tabs">${items.map(([k,label])=>`<button data-filter="${k}" class="${filter===k?'selected':''}">${label}</button>`).join('')}</div>`;}
function score(m){return (Date.parse(effectiveDeadline(state,m))<Date.now()?100:0)+m.resistance*4+m.slipRate*2;}
function getMissions(){return state.missions.filter(m=>(filter==='completed'?m.status==='completed':filter==='failed'?m.status==='failed':m.status==='active'&&(filter!=='today'||!m.repeatable&&localDateTime(effectiveDeadline(state,m)).slice(0,10)===today())&&(filter!=='overdue'||Date.parse(effectiveDeadline(state,m))<Date.now()))&&matchesOrganization(state,m,orgFilters.missions)&&`${m.title} ${m.description} ${itemTags(state,m).map(t=>tagPath(state.tags,t)).join(' ')}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='recent'?Date.parse(b.createdAt)-Date.parse(a.createdAt):sort==='name'?a.title.localeCompare(b.title):sort==='xp'?xpFor(b)-xpFor(a):sort==='due'?Date.parse(effectiveDeadline(state,a))-Date.parse(effectiveDeadline(state,b)):score(b)-score(a));}
function missionRows(items){return items.length?items.map(m=>`<article class="mission-row ${m.status==='completed'?'done':''}"><button class="complete" data-complete="${m.id}" ${m.status!=='active'?'disabled':''} aria-label="Complete ${esc(m.title)}">${m.status==='completed'?'✓':''}</button><button class="mission-main" data-quest="${m.id}">${art(m)}<div><b>${esc(m.title)}</b><p>${esc(m.description)}</p><div class="metadata">${tagChips(m,3,true)}${m.repeatable?'<span>∞ REPEATABLE / '+m.completedUses+' cleared</span>':`<span class="${Date.parse(effectiveDeadline(state,m))<Date.now()&&m.status==='active'?'warning':''}">◷ ${esc(fmt(effectiveDeadline(state,m)))}</span>`}${m.reminderCount?`<span>◉ ${m.reminderCount} pre-alerts</span>`:''}${!m.repeatable&&m.repeat!=='none'?`<span>↻ ${esc(recurrenceLabel(m))}</span>`:''}${m.subtasks.length?`<span>${m.subtasks.filter(t=>t.done).length}/${m.subtasks.length} steps</span>`:''}${m.parent?'<span>↳ Child</span>':''}</div></div></button><div class="mission-reward"><b>+${xpFor(m)} <small>XP</small></b><span>€$ ${coinsFor(m).toLocaleString()}</span></div><button class="more" data-edit="mission:${m.id}" aria-label="Edit ${esc(m.title)}">⋯</button></article>`).join(''):'<div class="empty"><span>∅</span><h3>No missions in this view</h3><p>Change filters or add a mission.</p></div>';}
function missions(){return heading('// YOUR QUESTS','Missions','Choose a quest. Take the next step.','<button class="primary" data-action="new-mission">＋ New mission</button>')+`<div class="toolbar"><label class="search">⌕ <input id="search" placeholder="Search missions" value="${esc(query)}" aria-label="Search missions"></label><select id="sort" aria-label="Sort missions">${[['recent','Most Recent'],['due','Due date'],['xp','Highest XP'],['name','Name']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div>${organizationFilters('missions')}${tabs([['active','All'],['today','Today'],['overdue','Overdue'],['completed','Completed'],['failed','Failed']])}<div class="mission-list">${missionRows(getMissions())}</div>`;}

function skills(){const parent=state.skills.find(s=>s.id===selectedSkill&&!s.parentId),items=state.skills.filter(s=>parent?s.parentId===parent.id:!s.parentId);return heading('// ATTRIBUTE MODULES',parent?esc(parent.title):'Attributes',parent?'Each selected Skill earns 45% of this Attribute’s mission XP.':'Open an Attribute to view its Skills.',`<div class="heading-actions"><button class="secondary" data-action="manage-tags">Add tags</button>${parent?`<button class="primary" data-add-sub="${parent.id}">＋ Add Skill</button>`:'<button class="primary" data-action="new-skill">＋ New Attribute</button>'}</div>`)+(parent?`<div class="skill-detail-header"><button class="secondary" data-skill-back>← Attributes</button><button class="text-button" data-edit="skill:${parent.id}">Edit Attribute ↗</button><span>${parent.xp} XP / LVL ${level(parent.xp)}</span></div>`:'')+`<div class="card-grid">${items.map(s=>{const p=progress(s.xp);return `<article class="panel skill-card"><button class="skill-open" ${parent?`data-edit="skill:${s.id}"`:`data-skill-open="${s.id}"`}>${art(s)}<span class="card-kicker">${itemTags(state,s).map(t=>esc(t.name)).join(' · ')}</span><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></button><div class="level-line"><b>LVL ${p.level}</b><small>${s.xp} XP</small></div>${xpBar(s.xp)}<p class="muted">${p.current} / ${p.total} XP</p>${parent?'':`<button class="secondary full" data-skill-open="${s.id}">Skills / ${state.skills.filter(child=>child.parentId===s.id).length} ↗</button>`}<button class="text-button" data-edit="skill:${s.id}">Configure ↗</button></article>`;}).join('')}</div>`+(parent&&!items.length?'<div class="empty"><h3>No Skills</h3><p>Add a Skill, then select it on a quest.</p></div>':'');}

function vitalsPanel(){const v=vitals(state),peak={green:5,orange:20,red:29}[v.tone];return `<div class="vitals ${v.tone}" id="vitals" role="img" aria-label="Vitals ${v.label}: ${v.count} unfinished overdue missions; oldest ${v.days} days"><span>VITALS / ${v.label}</span><svg viewBox="0 0 180 64" aria-hidden="true"><path class="vitals-grid" d="M0 16h180M0 32h180M0 48h180M30 0v64M60 0v64M90 0v64M120 0v64M150 0v64"/><path class="heartbeat" d="M0 32H20L27 29 34 32H44L50 37 57 ${peak} 64 ${64-peak} 71 32H98L105 29 112 32H124L130 37 137 ${peak} 144 ${64-peak} 151 32H180"/></svg><small>${v.count?`${v.count} overdue / oldest ${v.days}d`:'All deadlines clear'}</small></div>`;}

function rewards(){return heading('// EURODOLLAR EXCHANGE','Exchange','Mission credits. Operator-defined rewards.','<button class="primary" data-action="new-reward">＋ New reward</button>')+`<div class="reward-banner"><span>€$</span><h2>${money(state.profile.coins)} <small>AVAILABLE</small></h2></div><div class="card-grid">${state.rewards.map(r=>`<article class="panel reward-card">${art(r)}<span class="card-kicker">${esc(r.category)}</span><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><p class="muted">${r.quantity<0?'Unlimited stock':`${r.quantity} in stock`} / ${r.purchases} redeemed</p><div class="card-actions"><button class="primary" data-buy="${r.id}" ${state.profile.coins<r.cost||r.quantity===0?'disabled':''}>Redeem / ${r.cost.toLocaleString()} €$</button><button class="more" data-edit="reward:${r.id}" aria-label="Edit reward">⋯</button></div>${r.inventory?`<div class="inventory">INVENTORY × ${r.inventory}<button class="text-button" data-use="${r.id}">Use one ↗</button></div>`:''}</article>`).join('')}</div>`;}
function journal(){return heading('// EVENT STREAM','Activity log','Local mission and exchange history.')+`<section class="panel">${state.history.length?state.history.map(h=>`<div class="history-row"><span>${h.type==='complete'?'✓':h.type==='fail'?'×':'€$'}</span><div><b>${esc(h.title)}</b><small>${esc(fmt(h.at))}</small></div><div>${h.xp?`+${h.xp} XP`:''}<small>${h.coins||0} €$</small></div></div>`).join(''):'<div class="empty">NO EVENTS RECORDED</div>'}</section>`;}
function settings(){draft??=structuredClone(state.settings.appearance);return heading('// SYSTEM CONFIG','Configuration','Appearance, alarms, and local data.')+`<div class="settings-grid"><section class="panel appearance-panel"><div class="panel-title"><h2>Appearance</h2><button class="primary" id="save-appearance" data-action="save-appearance" ${!dirty?'disabled':''}>Save${dirty?' *':''}</button></div><p id="appearance-status" role="status">${dirty?'Unsaved preview. Save these settings.':'Configuration saved.'}</p><div class="theme-grid">${Object.entries(themes).map(([id,t])=>`<button data-theme="${id}" class="theme-option ${draft.theme===id?'selected':''}"><span class="swatches"><i style="background:${t.accent}"></i><i style="background:${t.secondary}"></i><i style="background:${t.panel}"></i></span>${t.name}</button>`).join('')}</div><div class="setting"><span>Active theme</span><b id="active-theme">${esc(draft.theme==='custom'?'Custom':themes[draft.theme].name)}</b></div><label class="setting">Subtheme<select id="subtheme">${[['void','Void / high contrast'],['dim','Dim / softer panels'],['light','Daybreak / light']].map(([id,label])=>`<option value="${id}" ${draft.subtheme===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="color-grid">${[['accent','Signal'],['secondary','Secondary'],['bg','Background'],['panel','Panels'],['text','Text']].map(([k,l])=>`<label>${l}<input type="color" data-color="${k}" value="${draft[k]}"></label>`).join('')}</div><label class="setting">CRT scanlines<input id="scanlines" type="checkbox" ${draft.scanlines?'checked':''}></label><label class="setting">Compact rows<input id="compact" type="checkbox" ${draft.compact?'checked':''}></label><label class="field">Text size <output id="textScale-value">${draft.textScale}%</output><input id="textScale" type="range" min="85" max="140" step="5" value="${draft.textScale}"></label><label class="field">Interface size ratio <output id="uiScale-value">${draft.uiScale}%</output><input id="uiScale" type="range" min="85" max="120" step="5" value="${draft.uiScale}"></label><button class="text-button" data-action="discard-appearance">Discard preview</button></section><div><section class="panel"><h2>Operator settings</h2><button class="secondary full" data-action="profile">Edit pixel operator / upload GIF ↗</button><label class="file-button full">Upload character-screen background<input id="cover" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>${state.settings.cover?'<button class="text-button" data-action="clear-cover">Remove background</button>':''}</section><section class="panel data-panel"><h2>Local data</h2><p>Web and Android store data independently. JSON backups transfer profiles, missions, images, and history. V1 backups are migrated automatically.</p><button class="secondary full" data-action="export">↓ Export backup</button><label class="file-button full">↑ Import backup<input id="import" type="file" accept=".json,application/json"></label>${native?'':`<a class="secondary full" href="downloads/daemon-deck-debug.apk" download>↓ Android APK / Overhaul</a><a class="text-button" href="downloads/daemon-deck-source.zip" download>Project source ↗</a>`}</section></div></div><div class="alarm-settings">${native?permissionPanel():`<section class="panel"><h2>Web notifications</h2><p>Browser alerts work while this app is open. Use the Android APK for scheduled alarms with the app closed.</p><button class="secondary" data-action="web-notifications">Enable browser notifications</button><p class="muted" id="web-permission">${'Notification'in window?Notification.permission:'Unavailable in this browser'}</p></section>`}</div>${alertSettings()}${attentionSettings()}${calendarColorSettings()}${retentionSettings()}${soundSettings()}<section class="panel"><h2>History & progress</h2><button class="secondary full" data-action="audit">Completion audit log ↗</button><button class="text-button full" data-go="journal">Open activity log ↗</button><button class="danger full" data-action="reset-xp">Reset character, Attribute & Skill XP</button></section>`;}
function bind(){
 bindAttention();bindAlertSettings();bindCalendar();bindSounds();bindTagSettings();bindQuestTaps();bindOrganizationFilters();bindRetention();
 $$('[data-skill-open]').forEach(b=>b.onclick=()=>{selectedSkill=b.dataset.skillOpen;render();scrollTo(0,0);});
 $$('[data-skill-back]').forEach(b=>b.onclick=()=>{selectedSkill='';render();});
 $$('[data-add-sub]').forEach(b=>b.onclick=()=>{newSkillParent=b.dataset.addSub;openEditor('skill');});
 for(const id of ['textScale','uiScale'])if($('#'+id))$('#'+id).oninput=e=>{draft[id]=+e.target.value;$('#'+id+'-value').value=e.target.value+'%';markAppearance();};

 $$('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();go(b.dataset.go);});
 $$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 $$('[data-edit]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.edit.split(':');openEditor(type,id);});
 $$('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));
 $$('[data-permission]').forEach(b=>b.onclick=()=>window.DaemonNative.requestPermission(b.dataset.permission));
 $$('[data-complete]').forEach(b=>b.onclick=()=>confirmCompletion(b.dataset.complete));
 $$('[data-buy]').forEach(b=>b.onclick=()=>{if(mutate(()=>purchase(state,b.dataset.buy))){render();toast('REDEEMED / added to inventory');}});
 $$('[data-use]').forEach(b=>b.onclick=()=>{mutate(()=>{const r=state.rewards.find(r=>r.id===b.dataset.use);if(r.inventory>0)r.inventory--;});render();});
 if($('#search'))$('#search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};
 if($('#category'))$('#category').onchange=e=>{category=e.target.value;render();};
 if($('#sort'))$('#sort').onchange=e=>{sort=e.target.value;render();};
 $$('[data-theme]').forEach(b=>b.onclick=()=>{draft={...draft,...themes[b.dataset.theme],theme:b.dataset.theme};markAppearance(false);render();});
 $$('[data-color]').forEach(c=>c.oninput=()=>{draft[c.dataset.color]=c.value;markAppearance();});
 if($('#subtheme'))$('#subtheme').onchange=e=>{draft.subtheme=e.target.value;markAppearance();};
 for(const id of ['scanlines','compact'])if($('#'+id))$('#'+id).onchange=e=>{draft[id]=e.target.checked;markAppearance();};
 if($('#cover'))$('#cover').onchange=async e=>{try{const image=await readImage(e.target.files[0]);mutate(()=>state.settings.cover=image);render();}catch(e){toast(e.message);}};
 if($('#import'))$('#import').onchange=importBackup;
}
function markAppearance(custom=true){if(custom)draft.theme='custom';dirty=JSON.stringify(draft)!==JSON.stringify(state.settings.appearance);applyAppearance(draft);if($('#save-appearance')){$('#save-appearance').disabled=!dirty;$('#save-appearance').textContent=dirty?'Save *':'Save';$('#appearance-status').textContent=dirty?'Unsaved preview. Save these settings.':'Configuration saved.';$('#active-theme').textContent=draft.theme==='custom'?'Custom':themes[draft.theme].name;$$('[data-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.theme===draft.theme));}}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function rating(name,label,value,labels,max){return `<label class="field rating">${label}<output id="${name}-value">${labels?esc(labels[value-1]):value}</output><input type="range" name="${name}" min="1" max="${max}" step="1" value="${value}" list="${name}-ticks"><datalist id="${name}-ticks">${Array.from({length:max},(_,i)=>`<option value="${i+1}"></option>`).join('')}</datalist><span class="notch-labels">${Array.from({length:max},(_,i)=>`<span>${i+1}</span>`).join('')}</span></label>`;}
function descendant(child,parent){const seen=new Set();while(child&&!seen.has(child)){if(child===parent)return true;seen.add(child);child=state.missions.find(m=>m.id===child)?.parent;}return false;}
function openEditor(type,id){const collection={mission:'missions',skill:'skills',reward:'rewards'}[type],old=state[collection]?.find(i=>i.id===id),x=old||{...missionDefaults(),kind:newQuestKind,dueAt:newQuestDate||missionDefaults().dueAt,cost:5000,quantity:-1,increase:0};editingImage=type==='profile'?state.profile.avatar:x.image||'';if(type==='profile')characterDraft=structuredClone(state.profile.character);if(!old){x.tagIds=[];x.primaryTagId='';}if(type==='mission'&&!old){x.recurrence=defaultRecurrence(x.dueAt);x.calendar.color=pickColor(state.settings.calendar.palette,state.missions.map(m=>m.calendar.color));}$('#editor').className='';
 $('#editor').innerHTML=`<form id="item-form"><div class="modal-heading"><div><span class="eyebrow">// CONFIGURATION</span><h2>${type==='profile'?'Operator editor':`${old?'Edit':'New'} ${type==='mission'?(x.kind==='side'?'side quest':'mission'):type==='skill'?((old?.parentId||!old&&newSkillParent)?'Skill':'Attribute'):type}`}</h2></div><button class="close" type="button" data-close aria-label="Close">×</button></div>${type==='profile'?profileFields():`${field('Name','title',x.title,'text','required maxlength="160"')}<label class="field">Description<textarea name="description" rows="2" maxlength="3000">${esc(x.description)}</textarea></label>${type==='skill'?entityTagFields(old):''}${tagSelector(type==='mission'?x:{...x,kind:undefined,skills:[]})}<div class="form-grid">${field('Icon / emoji','icon',x.icon,'text','maxlength="12"')}</div>${iconPicker(x.icon)}${uploadField('Upload icon / image',x.image)}${type==='mission'?missionFields(x,id):type==='reward'?`<div class="form-grid">${field('Cost / €$','cost',x.cost,'number','min="0" max="100000000" required')}${field('Stock (−1 = unlimited)','quantity',x.quantity,'number','min="-1" max="1000000" required')}${field('Cost increase per redemption','increase',x.increase,'number','min="0" max="100000000" required')}</div>`:''}${type!=='reward'?`<label class="field">Private notes<textarea name="notes" rows="3" maxlength="20000">${esc(x.notes)}</textarea></label>`:''}` }<div id="editor-error" class="form-error" role="alert"></div><div class="modal-actions">${old?`<button type="button" class="danger" data-delete>Delete</button>${type==='mission'?`${old.status!=='completed'?`<button type="button" class="secondary" data-status>${old.status==='active'?'Mark failed':'Reopen'}</button>`:''}<button type="button" class="secondary" data-duplicate>Duplicate</button>`:''}`:''}<span></span><button type="button" class="secondary" data-close>Cancel</button><button class="primary" type="submit">Save ${type==='profile'?'operator':type==='skill'?((old?.parentId||!old&&newSkillParent)?'Skill':'Attribute'):type}</button></div></form>`;
 const modal=$('#editor');modal.querySelectorAll('[data-pick-icon]').forEach(b=>b.onclick=()=>{modal.querySelector('[name=icon]').value=b.dataset.pickIcon;modal.querySelectorAll('[data-pick-icon]').forEach(btn=>{btn.classList.toggle('selected',btn===b);btn.setAttribute('aria-pressed',String(btn===b));});});if(!modal.open)modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());
 const upload=modal.querySelector('[name=image]');upload.onchange=async e=>{try{editingImage=await readImage(e.target.files[0],type==='profile');const img=modal.querySelector('.image-preview');img.src=editingImage;img.hidden=false;if(type==='profile')updateCharacterPreview();}catch(e){toast(e.message);}};
 if(type==='mission')bindSkillAssignments();if(type==='profile'){setupCharacterStudio();bindCharacter();}else bindTagSelector(type==='mission'?x:{...x,kind:undefined,skills:[]});bindIconSearch();
 if(type==='mission'){
  const updateXP=()=>{const f=Object.fromEntries(new FormData($('#item-form')));for(const [name,labels] of [['friction',null],['resistance',resistanceLabels],['slipRate',slipLabels],['drain',drainLabels]])$('#'+name+'-value').value=labels?labels[+f[name]-1]:f[name];const enabled=$('[name=xpEnabled]').checked;$('#rating-fields').classList.toggle('disabled',!enabled);const params={...f,xpEnabled:enabled,friction:+f.friction,resistance:+f.resistance,slipRate:+f.slipRate,drain:+f.drain};$('#xp-preview').textContent=`${xpFor(params)} XP`;if($('[name=coinMode]').value==='auto')$('[name=coins]').value=defaultCoins(params);$('#credit-payout').textContent=coinsFor({...params,kind:x.kind,coinMode:$('[name=coinMode]').value,coins:+$('[name=coins]').value})+' €$ FINAL';$('#credit-mode').textContent=$('[name=coinMode]').value==='auto'?'XP DEFAULT / 100 €$ PER 5 XP':'MANUAL OVERRIDE';};
  modal.querySelectorAll('.rating input,[name=xpEnabled]').forEach(input=>input.oninput=updateXP);$('[name=coins]').oninput=()=>{$('[name=coinMode]').value='manual';updateXP();};$('[data-reset-coins]').onclick=()=>{$('[name=coinMode]').value='auto';updateXP();};
  const updateReminders=(keep=false)=>{if($('[name=repeatable]')?.checked)return;const f=Object.fromEntries(new FormData($('#item-form')));let created=x.createdAt,due=new Date(f.dueAt);if(!Number.isFinite(+due))return;let count=+f.reminderCount,mode=f.reminderMode,at=reminderTimes({...x,dueAt:due.toISOString(),reminderCount:count,reminderMode:'even'});if(keep&&mode==='manual'){const current=$$('[name=reminderAt]').map(input=>input.value);at=at.map((v,i)=>current[i]?new Date(current[i]).toISOString():v);}$('#reminder-timeline').innerHTML=at.map((v,i)=>`<label class="reminder-slot"><span>0${i+1}</span><input type="datetime-local" name="reminderAt" value="${localDateTime(v)}" ${mode==='even'?'readonly':'required'} aria-label="Pre-reminder ${i+1}">${Date.parse(v)<Date.now()?'<small>ELAPSED</small>':''}</label>`).join('')+`<div class="due-slot"><b>◉ DUE</b><span>${esc(fmt(due))}</span></div>`;};
  $('[name=dueAt]').onchange=()=>updateReminders(false);$('[name=reminderCount]').onchange=()=>updateReminders(true);$('[name=reminderMode]').onchange=()=>updateReminders(false);bindQuestSchedule(x);bindSlots($('#editor'));bindMissionAlerts(x);setupCreator();updateXP();
 }
 if(old)modal.querySelector('[data-delete]').onclick=()=>{if(!confirm(`Delete “${old.title}”?`))return;if(mutate(()=>{state[collection]=state[collection].filter(i=>i.id!==id);if(type==='skill'){const removed=new Set([id,...state.skills.filter(s=>s.parentId===id).map(s=>s.id)]);state.skills=state.skills.filter(s=>!removed.has(s.id));state.missions.forEach(m=>m.skills=m.skills.filter(s=>!removed.has(s)));if(selectedSkill===id)selectedSkill='';}if(type==='mission')state.missions.forEach(m=>{if(m.parent===id)m.parent='';});})){modal.close();render();}};
 if(modal.querySelector('[data-status]'))modal.querySelector('[data-status]').onclick=()=>{if(mutate(()=>{const current=state[collection].find(x=>x.id===id);current.status=current.status==='active'?'failed':'active';if(current.status==='failed')state.history.unshift({id:uid(),type:'fail',title:old.title,at:new Date().toISOString()});})){modal.close();render();}};
 if(modal.querySelector('[data-duplicate]'))modal.querySelector('[data-duplicate]').onclick=()=>{if(mutate(()=>{const base=missionDefaults();state.missions.push({...structuredClone(old),id:uid(),title:old.title+' (copy)',status:'active',parent:'',seriesId:uid(),occurrence:1,completedUses:0,createdAt:base.createdAt,dueAt:old.repeatable?'':base.dueAt,calendar:{...old.calendar,uid:''},reminderMode:'even',reminderTimes:[],subtasks:old.subtasks.map(t=>({...t,done:false}))});})){modal.close();render();}};
 $('#item-form').onsubmit=e=>{e.preventDefault();if(type==='mission'&&!validateCreator(e.target))return;const f=new FormData(e.target),v=Object.fromEntries(f);try{
  if(type==='profile'){const c=characterFromForm();if(c.mode==='image'&&!editingImage&&!v.removeImage)throw Error('Upload an image or GIF, or select Pixel operator.');if(mutate(()=>{state.profile.name=v.name.trim()||'Operator';state.profile.title=v.title;state.profile.avatar=v.removeImage?'':editingImage;state.profile.character={...c,mode:v.removeImage?'pixel':c.mode};})){modal.close();render();toast('OPERATOR SAVED');}return;}
  if(!v.title.trim())throw Error('Name is required.');let item={...old,id:id||x.id,title:v.title.trim(),description:v.description,category:'',tagIds:f.getAll('tagIds'),primaryTagId:v.primaryTagId||'',icon:v.icon||'⌁',image:v.removeImage?'':editingImage};
  if(type==='mission'){Object.assign(item,{alerts:{alarms:$$('[name=alertAlarm]').map(i=>i.checked),dueAlarm:!!v.dueAlarm,notification:JSON.parse($('[name=missionNotificationSound]').value),alarm:JSON.parse($('[name=missionAlarmSound]').value)},duration:+v.duration,coins:+v.coins,coinMode:v.coinMode,kind:x.kind,repeatable:!!v.repeatable,completedUses:old?.completedUses||0,seriesId:old?.seriesId||x.seriesId,occurrence:old?.occurrence||1,recurrence:recurrenceFromForm(f),calendar:calendarFromForm(f,x),friction:+v.friction,resistance:+v.resistance,slipRate:+v.slipRate,drain:+v.drain,xpEnabled:f.has('xpEnabled'),repeat:v.repeatable?'none':v.repeat,createdAt:x.createdAt,dueAt:v.repeatable?'':new Date(v.dueAt).toISOString(),reminderCount:v.repeatable?0:+v.reminderCount,reminderMode:v.repeatable?'even':v.reminderMode,reminderTimes:!v.repeatable&&v.reminderMode==='manual'?f.getAll('reminderAt').map(d=>new Date(d).toISOString()):[],skills:f.getAll('skills'),parent:v.parent,notes:v.notes,location:v.location,status:old?.status||'active',subtasks:v.steps.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>{const i=x.subtasks.findIndex(s=>s.title===t);return {title:t,done:i>=0&&f.getAll('stepdone').includes(String(i))};})});checkSchedule(item);if(!item.repeatable&&(!old||old.dueAt!==item.dueAt)&&Date.parse(item.dueAt)<=Date.now())throw Error('Choose a future due date.');}
  if(type==='skill')Object.assign(item,{xp:old?.xp||0,notes:v.notes,parentId:old?old.parentId:(newSkillParent||''),boundTagId:v.boundTagId||undefined});if(type==='reward')Object.assign(item,{cost:+v.cost,quantity:+v.quantity,increase:+v.increase,purchases:old?.purchases||0,inventory:old?.inventory||0});
  if(mutate(()=>{if(old)state[collection]=state[collection].map(o=>o.id===id?item:o);else state[collection].push(item);if(type==='skill'){pairEntityTag(state,item,v.boundTagId||'');syncEntityName(state,item);}})){modal.close();render();toast('SAVED');}
 }catch(e){if($('#editor').classList.contains('quest-creator')&&/slot|deadline|recurrence|reminder|date/i.test(e.message))showCreatorTab('schedule');$('#editor-error').textContent=e.message;$('#editor-error').scrollIntoView({block:'nearest'});}};
}
function uploadField(label,image){return `<label class="file-button full">↑ ${label}<input name="image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label><img class="image-preview" ${image?`src="${esc(image)}"`:'hidden'} alt="Image preview"><label class="check-label"><input name="removeImage" type="checkbox"> Remove uploaded image</label>`;}
function missionFields(x,id){return `${questScheduleFields(x)}${missionAlertFields(x)}<section class="editor-section"><div class="panel-title"><h3>XP parameters</h3><label class="switch-label"><input type="checkbox" name="xpEnabled" ${x.xpEnabled?'checked':''}> Earn XP</label></div><div id="rating-fields" class="range-fields">${rating('friction','Friction',x.friction,null,5)}${rating('resistance','Resistance',x.resistance,resistanceLabels,5)}${rating('slipRate','Slip Rate',x.slipRate,slipLabels,4)}${rating('drain','Drain',x.drain,drainLabels,4)}</div><div class="xp-preview"><span>MISSION PAYOUT</span><b id="xp-preview">${xpFor(x)} XP</b></div><details class="xp-help"><summary>How XP is calculated</summary><p class="fine-print">Drain has the largest XP effect (+0 / 24 / 56 / 96). Friction and Resistance add up to 48 each; Slip Rate adds up to 48.</p></details></section><div class="form-grid"><div class="currency-editor">${field('Base €$ / side quests pay 50%','coins',x.coinMode==='manual'?x.coins:defaultCoins(x),'number','min="0" max="100000000" step="1" required')}<input type="hidden" name="coinMode" value="${x.coinMode}"><b id="credit-payout">${coinsFor(x)} €$ FINAL</b><small id="credit-mode">${x.coinMode==='auto'?'XP DEFAULT / 100 €$ PER 5 XP':'MANUAL OVERRIDE'}</small><button type="button" class="secondary full" data-reset-coins>Reset to XP default</button></div></div>${questCalendarFields(x)}${select('Parent mission','parent',[['','Standalone'],...state.missions.filter(m=>m.id!==id&&m.status==='active'&&!descendant(m.id,id)).map(m=>[m.id,m.title])],x.parent||'')}<fieldset class="xp-assignment"><legend>Attributes & Skills</legend><p class="fine-print">Enable an Attribute to unlock its Skills. Turning it off clears its selected Skills. Attributes earn full XP; each selected Skill earns 45%.</p><div data-auto-tags></div>${state.skills.filter(p=>!p.parentId).map(parent=>`<div class="xp-attribute-group">${assignmentChoice(parent,x)}<div class="xp-skill-list">${state.skills.filter(c=>c.parentId===parent.id).map(child=>assignmentChoice(child,x)).join('')}</div></div>`).join('')}</fieldset><label class="field">Subtasks <small>One per line. Existing steps can be checked below.</small><textarea name="steps" rows="3">${esc(x.subtasks.map(t=>t.title).join('\n'))}</textarea></label>${x.subtasks.map((t,i)=>`<label class="check-label"><input type="checkbox" name="stepdone" value="${i}" ${t.done?'checked':''}>${esc(t.title)}</label>`).join('')}${field('Location','location',x.location||'','text','maxlength="300"')}`;}
function colorControl(name,label,value){return `<label>${esc(label)}<input name="${name}" type="color" value="${value}"></label>`;}
function paletteFields(c){const outfit=outfitPalette(c),item=itemPalette(c);return `<section class="editor-section"><h3>Outfit parts / ${esc(clothesNames[c.clothes])}</h3><div class="color-grid part-colors">${outfitParts[c.clothes].map(p=>colorControl(`cloth:${c.clothes}:${p.key}`,p.label,outfit[p.key])).join('')}</div></section><section class="editor-section"><h3>Equipment parts / ${esc(itemNames[c.accessory])}</h3>${itemParts[c.accessory].length?`<div class="color-grid part-colors">${itemParts[c.accessory].map(p=>colorControl(`gear:${c.accessory}:${p.key}`,p.label,item[p.key])).join('')}</div>`:'<p class="muted">Select equipment to edit its colors.</p>'}</section>`;}
function profileFields(){const c=characterDraft;return `<div id="character-preview" class="editor-character">${characterView(c)}</div>${field('Handle','name',state.profile.name,'text','required maxlength="60"')}${field('Designation','title',state.profile.title,'text','maxlength="100"')}${select('Display mode','characterMode',[['pixel','Pixel operator'],['image','Custom image / animated GIF']],c.mode)}<section class="editor-section"><h3>Body & hair</h3>${select('Build','bodyType',[[0,'Classic'],[1,'Broad'],[2,'Slim']],c.bodyType)}${select('Hairstyle','hair',hairNames.map((n,i)=>[i,n]),c.hair)}<div class="color-grid">${colorControl('skin','Skin',c.skin)}${colorControl('hairColor','Hair',c.hairColor)}${colorControl('hairAccent','Hair accent',c.hairAccent)}${colorControl('outline','Outline / seams',c.outline)}</div></section><section class="editor-section eye-category"><h3>Face & eyes</h3>${select('Face shape','faceType',faceNames.map((n,i)=>[i,n]),c.faceType)}${select('Expression','mouthStyle',mouthNames.map((n,i)=>[i,n]),c.mouthStyle)}${select('Brows','browStyle',browNames.map((n,i)=>[i,n]),c.browStyle)}${select('Facial hair','beardStyle',beardNames.map((n,i)=>[i,n]),c.beardStyle)}${select('Eye shape','eyeStyle',eyeNames.map((n,i)=>[i,n]),c.eyeStyle)}<div class="color-grid">${colorControl('eyes','Iris',c.eyes)}${colorControl('eyeWhite','White / highlight',c.eyeWhite)}${colorControl('pupilColor','Pupil',c.pupilColor)}${colorControl('lipColor','Mouth',c.lipColor)}${colorControl('browColor','Brows',c.browColor)}${colorControl('beardColor','Facial hair',c.beardColor)}</div></section><div class="form-grid">${select('Clothing','clothes',clothesNames.map((n,i)=>[i,n]),c.clothes)}${select('Item','accessory',itemNames.map((n,i)=>[i,n]),c.accessory)}</div><div id="palette-fields">${paletteFields(c)}</div><label class="field">Character size ratio <output id="character-scale-value">${c.scale}%</output><input type="range" name="scale" min="60" max="160" step="5" value="${c.scale}"></label>${uploadField('Upload operator image / GIF',state.profile.avatar)}<p class="fine-print">24 × 32 pixel operator. Each clothing style and item remembers its own palette. Animated GIF uploads retain animation (1.5 MB maximum).</p>`;}
function characterFromForm(){const f=Object.fromEntries(new FormData($('#item-form'))),c=structuredClone(characterDraft);Object.assign(c,{faceType:+f.faceType,mouthStyle:+f.mouthStyle,browStyle:+f.browStyle,beardStyle:+f.beardStyle,bodyType:+f.bodyType,outline:f.outline,lipColor:f.lipColor,browColor:f.browColor,beardColor:f.beardColor,hairAccent:f.hairAccent,hair:+f.hair,accessory:+f.accessory,clothes:+f.clothes,scale:+f.scale,skin:f.skin,hairColor:f.hairColor,eyes:f.eyes,eyeStyle:+f.eyeStyle,eyeWhite:f.eyeWhite,pupilColor:f.pupilColor,mode:f.characterMode});for(const [name,value] of Object.entries(f)){const match=/^(cloth|gear):(\d+):([a-z]+)$/.exec(name);if(!match)continue;const map=match[1]==='cloth'?c.outfitColors:c.itemColors;map[match[2]]??={};map[match[2]][match[3]]=value;}return c;}
function updateCharacterPreview(){characterDraft=characterFromForm();$('#character-preview').innerHTML=characterView(characterDraft,editingImage);$('#character-scale-value').value=characterDraft.scale+'%';}
function bindCharacter(){$$('#item-form select,#item-form input[type=color],#item-form input[type=range]').forEach(input=>input.oninput=()=>{updateCharacterPreview();$$('[data-character-pick]').forEach(b=>b.setAttribute('aria-pressed',String($('[name='+b.dataset.characterPick+']').value===b.dataset.value)));if(['clothes','accessory'].includes(input.name)){$('#palette-fields').innerHTML=paletteFields(characterDraft);bindCharacter();}});}
function openSkillRadar(){const modal=$('#editor');modal.className='radar-dialog';const main=state.skills.filter(s=>!s.parentId),all=main.flatMap(p=>[p,...state.skills.filter(s=>s.parentId===p.id)]);modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// OPERATOR STATS</span><h2>Attributes & Skills web</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div><p class="muted">All Attributes and Skills. Every point uses the same XP scale.</p><div class="radar-full-chart">${radarSvg(all,true)}</div><div class="radar-full-legend">${all.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s.parentId?'↳ ':''}${esc(s.title)}${s.parentId?`<small>${esc(main.find(p=>p.id===s.parentId)?.title||'')}</small>`:''}</b><span>${s.xp} XP</span></div>`).join('')}</div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.showModal();}

async function readImage(file,preserveGif=false){if(!file)throw Error('Select an image.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use PNG, JPG, WebP, or GIF.');if(file.size>10*1024*1024)throw Error('Image limit: 10 MB.');if(preserveGif&&file.type==='image/gif'){if(file.size>1500000)throw Error('Animated GIF limit: 1.5 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Could not read GIF.'));r.readAsDataURL(file);});}return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(Error('Could not read image.'));r.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Invalid image.'));img.onload=()=>{const c=document.createElement('canvas'),ratio=Math.min(1,1200/Math.max(img.width,img.height));c.width=Math.max(1,Math.round(img.width*ratio));c.height=Math.max(1,Math.round(img.height*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/webp',.8));};img.src=r.result;};r.readAsDataURL(file);});}
function download(content,name){if(native){window.DaemonNative.exportBackup(content,name);return;}const url=URL.createObjectURL(new Blob([content],{type:name.endsWith('.ics')?'text/calendar':'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importBackup(e){try{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Backup limit: 25 MB.');const incoming=validate(JSON.parse(await file.text()));if(dirty&&!confirm('Discard unsaved appearance settings before import?'))return;if(!confirm('Replace local data with this backup? Export your current data first to keep it.'))return;if(mutate(()=>state=incoming)){dirty=false;orgFilters.calendar={attributes:[],skills:[],tags:[],match:'any'};orgFilters.missions={attributes:[],skills:[],tags:[],match:'any'};draft=structuredClone(state.settings.appearance);render();toast('BACKUP RESTORED');}}catch(e){toast(e.message);}}
async function action(a){if(a==='audit')return showCompletionAudit();if(a==='reset-xp')return confirmXPReset();if(a==='new-mission')return chooseQuest();if(a==='calendar-new'){{const selected=new Date(localDay(calendarDate)+'T12:00:00');newQuestDate=(localDay(selected)===today()&&selected<=new Date()?new Date(Date.now()+3600000):selected).toISOString();}return chooseQuest(true);}if(a.startsWith('new-')){newSkillParent='';return openEditor(a.slice(4));}if(a==='manage-tags')return openTagManager();if(a==='quest-detail')return;if(a==='calendar-date')return openCalendarDate();if(a==='calendar-tools')return calendarTools();if(a==='calendar-view')return calendarViewPicker();if(a==='calendar-search'){calendarSearchOpen=!calendarSearchOpen;render();$('#calendar-search')?.focus();return;}if(a==='profile')return openEditor('profile');if(a==='radar')return openSkillRadar();if(a==='refresh-permissions'){render();syncAlarms();}if(a==='test-alarm')window.DaemonNative.testAlarm();if(a==='save-appearance'){saveAppearance();render();}if(a==='discard-appearance'){draft=structuredClone(state.settings.appearance);dirty=false;render();}if(a==='clear-cover'){mutate(()=>state.settings.cover='');render();}if(a==='export')download(JSON.stringify(state,null,2),`daemon-deck-${today()}.json`);if(a==='export-raw')download(localStorage.getItem('daemon-deck')||'{}','daemon-deck-original.json');if(a==='web-notifications'){if(!('Notification'in window)){toast('Notifications unavailable in this browser.');return;}const result=await Notification.requestPermission();$('#web-permission').textContent=result;if(result==='denied')toast('Notifications blocked. Change this site’s browser permissions to enable.');}}
window.daemonRefreshPermissions=()=>{render();syncAlarms();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='Save these settings';}});
// Browser notifications are session-only. Persist delivered IDs to avoid duplicates on reload.
let lastWebCheck=Date.now();setInterval(()=>{if(native)return;const now=Date.now();const events=alarmPlan(state,lastWebCheck-1).filter(a=>a.at<=now);if('Notification'in window&&Notification.permission==='granted'){let fired;try{fired=JSON.parse(localStorage.getItem('daemon-web-fired')||'[]');}catch{fired=[];}for(const event of events){const key=event.id+':'+event.at;if(fired.includes(key))continue;try{new Notification(event.title,{body:event.body,icon:'icon.svg',tag:event.id});fired.push(key);}catch{}}try{localStorage.setItem('daemon-web-fired',JSON.stringify(fired.slice(-1000)));}catch{}}lastWebCheck=now;},15000);
setInterval(()=>{if($('#vitals'))$('#vitals').outerHTML=vitalsPanel();},60000);
if(pruneCalendarHistory(state).length)persist();render();syncAlarms();if('serviceWorker'in navigator&&!native)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function iconPicker(value){return `<details class="icon-library"><summary>Choose icon / 200 symbols</summary><label class="icon-search-label"><span class="sr-only">Search icons</span><input type="search" data-icon-search placeholder="Search 200 icons…"></label><div class="icon-picker">${icons.map(i=>`<button type="button" data-pick-icon="${i.id}" class="${value===i.id?'selected':''}" aria-label="${i.label} icon" aria-pressed="${value===i.id}">${iconSvg(i.id)}<small>${i.label}</small></button>`).join('')}</div></details>`;}
function chooseQuest(fromCalendar=false){if(!fromCalendar)newQuestDate='';const modal=$('#editor');modal.className='';modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// NEW QUEST</span><h2>Select quest type</h2></div><button type="button" class="close" data-close aria-label="Close">×</button></div><div class="quest-type-grid"><button type="button" class="quest-type" data-kind="main"><span>⚑</span><b>Mission</b><small>Full XP · full credits<br>Scheduled deadline and recurrence</small></button><button type="button" class="quest-type side" data-kind="side"><span>◇</span><b>Side Quest</b><small>Full XP · 50% credits<br>Optional unlimited Repeatable mode</small></button></div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{newQuestKind=b.dataset.kind;openEditor('mission');if(fromCalendar){$('[name=calEnabled]').checked=true;updateQuestVisibility();}});if(!modal.open)modal.showModal();}
function questScheduleFields(x){const r=recurrenceFor(x),dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<div class="quest-type-banner ${x.kind}">${x.kind==='side'?'◇ SIDE QUEST / 50% €$ · 100% XP':'⚑ MAIN MISSION / FULL PAYOUT'}</div>${x.kind==='side'?`<label class="setting"><span>Repeatable <small>Unlimited uses. No deadline. Stays on the board until deleted.</small></span><input type="checkbox" name="repeatable" ${x.repeatable?'checked':''}></label>`:''}<section class="editor-section"><h3>Schedule & recurrence</h3><div data-deadline-fields><p class="muted">Created ${esc(fmt(x.createdAt))}. Pre-reminders divide creation → due time.</p><div class="form-grid">${field('Due date & time','dueAt',localDateTime(x.dueAt||new Date(Date.now()+86400000)),'datetime-local','required')}${select('Pre-reminders','reminderCount',Array.from({length:6},(_,i)=>[i,String(i)]),x.reminderCount)}${select('Reminder timing','reminderMode',[['even','Evenly spaced'],['manual','Custom times']],x.reminderMode)}</div><div id="reminder-timeline">${reminderTimes(x).map((v,i)=>`<label class="reminder-slot"><span>0${i+1}</span><input type="datetime-local" name="reminderAt" value="${localDateTime(v)}" ${x.reminderMode==='even'?'readonly':'required'} aria-label="Pre-reminder ${i+1}"></label>`).join('')}<div class="due-slot"><b>◉ DUE</b><span>${x.dueAt?esc(fmt(x.dueAt)):'No deadline'}</span></div></div><p class="fine-print">${native?'Android stores deadline alarms while the app is closed.':'Web alerts require an open tab; Android provides background alarms.'}</p>${select('Repeat schedule','repeat',[['none','No repeat'],['daily','Daily'],['weekly','Weekly'],['biweekly','Biweekly / every 2 weeks'],['monthly','Monthly'],['yearly','Yearly']],x.repeat)}<div data-repeat-details><div class="form-grid">${field('Interval multiplier','repeatInterval',r.interval,'number','min="1" max="365" required')}<p class="muted">Daily: every N days. Weekly: every N weeks. Biweekly: every 2 × N weeks. Monthly: every N months. Yearly: every N years.</p></div><fieldset data-weekly><legend>Repeat on</legend>${dayNames.map((d,i)=>`<label class="skill-check"><input type="checkbox" name="repeatDays" value="${i}" ${r.weekdays.includes(i)?'checked':''}>${d}</label>`).join('')}</fieldset><div data-monthly>${select('Month / yearly pattern','monthlyMode',[['date','Day of month'],['weekday','Ordinal weekday']],r.monthlyMode)}<div class="form-grid"><div data-month-date>${field('Day of month','monthDay',r.monthDay,'number','min="1" max="31" required')}${select('Short months','missingDay',[['last','Use last day'],['skip','Skip that month']],r.missingDay)}</div><div data-month-week>${select('Which week','weekOrdinal',[[1,'First'],[2,'Second'],[3,'Third'],[4,'Fourth'],[5,'Fifth'],[-1,'Last']],r.weekOrdinal)}${select('Weekday','repeatWeekday',dayNames.map((d,i)=>[i,d]),r.weekday)}</div></div></div>${select('End recurrence','repeatEnd',[['never','Never'],['until','On a date'],['count','After N occurrences']],r.end)}<div data-end-until>${field('Last recurrence date','repeatUntil',r.until||localDay(new Date(Date.now()+365*86400000)),'date','required')}</div><div data-end-count>${field('Total occurrences (including first)','repeatCount',r.count,'number','min="1" max="10000" required')}</div><p class="fine-print">Completing a scheduled quest creates its next future occurrence. Missed dates are skipped; the end date/count still applies. Local clock time is preserved across daylight saving changes. Week-based schedules start Monday.</p></div></div>${field('Estimated minutes','duration',x.duration,'number','required min="1" max="100000"')}</section>`;}
function questCalendarFields(x){const c=x.calendar;return `<section class="editor-section"><label class="setting"><span>Add to Calendar <small>Only opted-in quests appear in Calendar.</small></span><input type="checkbox" name="calEnabled" ${c.enabled?'checked':''}></label><div data-calendar-fields><div class="quest-type-banner ${x.kind}">PRIMARY TAG: ${x.kind==='side'?'SIDE QUEST':'MAIN'}</div><div class="form-grid">${field('Estimated event minutes','calDuration',c.duration,'number','min="1" max="10080" required')}<label class="field">Untagged event color<input type="color" name="calColor" value="${c.color}"></label></div><label class="check-label"><input type="checkbox" name="calAllDay" ${c.allDay?'checked':''}> All-day event</label>${slotFields(c.slots||[])}<label class="check-label"><input type="checkbox" name="calBusy" ${c.busy?'checked':''}> Mark as busy</label><p class="fine-print">Selected quest tags also label this event. The primary tag sets its title color; untagged quests use their assigned color.</p><label class="field">Calendar notes<textarea name="calNotes" maxlength="20000" rows="4">${esc(c.notes)}</textarea></label><p class="fine-print">Optional slots reserve specific hours on each scheduled date. Leave them blank for Any time at the top. Slots never add extra days; only recurrence does. The deadline stays independent. Calendar notes are separate from private quest notes. Exported calendar files include these notes and tags.</p></div><p data-repeatable-calendar class="fine-print">Repeatable side quests have no date. Turn Repeatable off to add this quest to Calendar.</p></section>`;}
function setGroup(selector,show){const group=$('#editor '+selector);if(!group)return;group.hidden=!show;group.querySelectorAll('input,select,textarea').forEach(i=>i.disabled=!show);}
function updateQuestVisibility(){const infinite=!!$('[name=repeatable]')?.checked,freq=$('[name=repeat]')?.value||'none';setGroup('[data-deadline-fields]',!infinite);setGroup('[data-repeat-details]',!infinite&&freq!=='none');setGroup('[data-weekly]',!infinite&&['weekly','biweekly'].includes(freq));setGroup('[data-monthly]',!infinite&&['monthly','yearly'].includes(freq));const monthly=$('[name=monthlyMode]')?.value;setGroup('[data-month-date]',!infinite&&['monthly','yearly'].includes(freq)&&monthly==='date');setGroup('[data-month-week]',!infinite&&['monthly','yearly'].includes(freq)&&monthly==='weekday');setGroup('[data-end-until]',!infinite&&freq!=='none'&&$('[name=repeatEnd]').value==='until');setGroup('[data-end-count]',!infinite&&freq!=='none'&&$('[name=repeatEnd]').value==='count');const cal=$('[name=calEnabled]');if(cal){cal.disabled=infinite;if(infinite)cal.checked=false;setGroup('[data-calendar-fields]',!infinite&&cal.checked);$('[data-repeatable-calendar]').hidden=!infinite;}}
function bindQuestSchedule(x){for(const name of ['repeatable','repeat','monthlyMode','repeatEnd','calEnabled'])if($(`[name=${name}]`))$(`[name=${name}]`).addEventListener('change',updateQuestVisibility);updateQuestVisibility();}
function recurrenceFromForm(f){if(f.has('repeatable'))return defaultRecurrence();const get=n=>f.get(n),due=get('dueAt'),base=defaultRecurrence(due);return {...base,frequency:get('repeat')||'none',interval:+(get('repeatInterval')||1),weekdays:['weekly','biweekly'].includes(get('repeat'))?f.getAll('repeatDays').map(Number):base.weekdays,monthlyMode:get('monthlyMode')||'date',monthDay:+(get('monthDay')||base.monthDay),weekOrdinal:+(get('weekOrdinal')||base.weekOrdinal),weekday:+(get('repeatWeekday')??base.weekday),missingDay:get('missingDay')||'last',end:get('repeatEnd')||'never',until:get('repeatUntil')||'',count:+(get('repeatCount')||10)};}
function calendarFromForm(f,x){return {...x.calendar,enabled:f.has('calEnabled')&&!f.has('repeatable'),slots:f.has('calAllDay')?[]:slotsFromForm(f),duration:+(f.get('calDuration')||x.calendar.duration),color:f.get('calColor')||x.calendar.color,allDay:f.has('calAllDay'),busy:f.has('calBusy'),tags:f.getAll('tagIds').map(id=>state.tags.find(t=>t.id===id)?.name).filter(Boolean),notes:f.get('calNotes')??x.calendar.notes};}
function confirmCompletion(id){
 const m=state.missions.find(m=>m.id===id);if(!m||m.status!=='active'){toast('This quest is already completed or inactive.');return;}
 const remaining=m.subtasks.filter(t=>!t.done).length,children=state.missions.filter(c=>c.parent===id&&c.status==='active'),modal=$('#editor'),expectedUses=m.completedUses;let submitting=false;
 modal.className='completion-dialog';modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">// CONFIRM EXECUTION</span><h2>Complete ${m.kind==='side'?'side quest':'mission'}?</h2></div><button class="close" data-close aria-label="Close">×</button></div><h3>${esc(m.title)}</h3><div class="completion-payout"><span>+${xpFor(m)} XP</span><span>+${coinsFor(m).toLocaleString()} €$</span></div>${remaining?`<label class="check-label completion-steps"><input type="checkbox" id="finish-subtasks" checked> Also complete ${remaining} remaining subtask${remaining===1?'':'s'}</label>`:''}${children.length?`<div class="completion-blockers"><p>Complete these child missions first:</p>${children.map(c=>`<button class="secondary full" data-blocking-child="${c.id}">${esc(c.title)} ↗</button>`).join('')}</div>`:''}<p class="muted">${m.repeatable?'This repeatable side quest stays active. Subtasks reset for the next use.':m.calendar.enabled?'The completed quest stays in Calendar with a check mark.':'This quest will move to Completed.'}${!m.repeatable&&m.repeat!=='none'?' The next scheduled occurrence will be created if its end rule allows.':''}</p><p id="editor-error" class="form-error" role="alert"></p><div class="modal-actions"><button class="secondary" data-completion-back>Back to quest</button><button class="primary" id="confirm-complete" ${children.length?'disabled':''}>Confirm completion</button></div>`;
 modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-completion-back]').onclick=()=>showQuest(id);modal.querySelectorAll('[data-blocking-child]').forEach(b=>b.onclick=()=>showQuest(b.dataset.blockingChild));
 const button=modal.querySelector('#confirm-complete'),finish=modal.querySelector('#finish-subtasks');if(finish)finish.onchange=()=>button.disabled=children.length>0||!finish.checked;
 button.onclick=()=>{if(submitting)return;submitting=true;button.disabled=true;const prior=structuredClone(state.profile),before=level(state.profile.xp),current=state.missions.find(q=>q.id===id),xp=xpFor(current),credits=coinsFor(current);unlockAudio().catch(()=>{});
 if(mutate(()=>{if(complete(state,id,new Date(),{finishSubtasks:!!finish?.checked,expectedUses})===null)throw Error('This completion has already been recorded.');})){modal.close();render();showReward({name:state.profile.name,before:prior,after:structuredClone(state.profile),xp,coins:credits,sounds:state.settings.sounds,reduced:state.settings.attention.reducedMotion});}else{submitting=false;button.disabled=false;}
 };if(!modal.open)modal.showModal();
}

function soundSettings(){const s=state.settings.sounds;return `<section class="panel sound-settings"><div class="panel-title"><h2>Sound deck</h2><label class="check-label"><input type="checkbox" id="sound-muted" ${s.muted?'checked':''}> Mute rewards</label></div><label class="field">Volume <output id="sound-volume-value">${s.volume}%</output><input type="range" id="sound-volume" min="0" max="100" value="${s.volume}"></label><p class="fine-print">Four original sounds per category. “Wasteland terminal” is an original retro sci-fi level-up cue. Local clips: up to 12 seconds / 550 KB each. Changes save immediately.</p><div class="sound-grid">${soundCategories.map(([id,title])=>`<section><h3>${title}</h3><select data-sound-select="${id}" aria-label="${title} sound">${soundNames[id].map((label,i)=>`<option value="${i}" ${s[id].mode==='preset'&&s[id].preset===i?'selected':''}>${label}</option>`).join('')}<option value="custom" ${s[id].mode==='custom'?'selected':''} ${!s[id].data?'disabled':''}>Local audio${s[id].name?' / '+esc(s[id].name):''}</option></select><div class="sound-actions"><button class="secondary" data-sound-preview="${id}">Preview</button><label class="file-button">Upload audio<input type="file" data-sound-upload="${id}" accept="audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/aac,audio/webm"></label></div>${s[id].data?`<button class="text-button" data-sound-clear="${id}">Remove local clip</button>`:''}</section>`).join('')}</div></section>`;}
function bindSounds(){if($('#sound-muted'))$('#sound-muted').onchange=e=>mutate(()=>state.settings.sounds.muted=e.target.checked);if($('#sound-volume'))$('#sound-volume').oninput=e=>{mutate(()=>state.settings.sounds.volume=+e.target.value);$('#sound-volume-value').value=e.target.value+'%';};$$('[data-sound-select]').forEach(input=>input.onchange=()=>{mutate(()=>{const a=state.settings.sounds[input.dataset.soundSelect];a.mode=input.value==='custom'?'custom':'preset';if(a.mode==='preset')a.preset=+input.value;});});$$('[data-sound-preview]').forEach(b=>b.onclick=()=>previewSound(b.dataset.soundPreview,state.settings.sounds).catch(()=>toast('This audio could not be played.')));$$('[data-sound-upload]').forEach(input=>input.onchange=async()=>{try{const data=await readAudio(input.files[0]);if(mutate(()=>Object.assign(state.settings.sounds[input.dataset.soundUpload],data,{mode:'custom'})))render();}catch(e){toast(e.message);}});$$('[data-sound-clear]').forEach(b=>b.onclick=()=>{mutate(()=>Object.assign(state.settings.sounds[b.dataset.soundClear],{data:'',name:'',mode:'preset'}));render();});}
function updateClock(){$$('.cyber-clock').forEach(el=>{const d=new Date();el.innerHTML=`<b>${d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})}</b><small>${d.toLocaleDateString([],{month:'short',day:'2-digit',year:'numeric'})}</small>`;el.dateTime=d.toISOString();});updateBattery();}
setInterval(updateClock,1000);
function calendarRange(){const d=new Date(calendarDate);d.setHours(0,0,0,0);if(calendarView==='day')return [d,new Date(d.getFullYear(),d.getMonth(),d.getDate()+1)];if(calendarView==='week'){d.setDate(d.getDate()-(d.getDay()+6)%7);return [d,new Date(d.getFullYear(),d.getMonth(),d.getDate()+7)];}const start=new Date(d.getFullYear(),d.getMonth(),1);if(calendarView==='month'){start.setDate(start.getDate()-(start.getDay()+6)%7);return [start,new Date(start.getFullYear(),start.getMonth(),start.getDate()+42)];}return [start,new Date(d.getFullYear(),d.getMonth()+1,1)];}
function eventStart(e){const t=e.timing||occurrenceTiming(state,e.quest,e.originalAt||e.at),slot=e.displaySlot||t.slots[0];return slot?slotDates(t,slot).start:new Date(t.day+'T00:00:00');}
function eventEnd(e){const t=e.timing||occurrenceTiming(state,e.quest,e.originalAt||e.at),slot=e.displaySlot||t.slots.at(-1);if(slot)return slotDates(t,slot).end;const d=new Date(t.day+'T00:00:00');d.setDate(d.getDate()+1);return d;}

function onDay(e,date){const start=new Date(localDay(date)+'T00:00:00'),end=new Date(start.getFullYear(),start.getMonth(),start.getDate()+1);return eventStart(e)<end&&eventEnd(e)>start;}
function calendarPage(){const [from,to]=calendarRange();calendarEntries=calendarEvents(state.missions,new Date(+from-8*86400000),to,state.calendarOverrides).filter(e=>matchesOrganization(state,e.quest,orgFilters.calendar)&&(calendarShowCompleted||e.projected||e.quest.status!=='completed')&&`${e.quest.title} ${e.quest.calendar.notes} ${itemTags(state,e.quest).map(t=>tagPath(state.tags,t)).join(' ')}`.toLowerCase().includes(calendarQuery.toLowerCase())&&eventEnd(e)>from);return `<section class="planner"><header class="planner-header"><div><span class="planner-overline">LOCAL CALENDAR</span><button class="planner-month" data-action="calendar-date">${calendarDate.toLocaleDateString([],{month:'long'})}<span>${calendarDate.getFullYear()}⌄</span></button></div><div class="planner-header-actions"><button class="planner-icon" data-calendar-today aria-label="Go to today">${new Date().getDate()}</button><button class="planner-icon" data-action="calendar-search" aria-label="Search calendar">⌕</button><button class="planner-icon" data-action="calendar-tools" aria-label="Calendar tools and filters">☰</button></div></header><div class="planner-controls"><div class="planner-step"><button class="planner-icon" data-calendar-step="-1" aria-label="Previous period">‹</button><button class="planner-view-button" data-action="calendar-view">${calendarView==='agenda'?'Schedule':calendarView[0].toUpperCase()+calendarView.slice(1)}⌄</button><button class="planner-icon" data-calendar-step="1" aria-label="Next period">›</button></div><button class="planner-create" data-action="calendar-new">＋ Add quest</button></div>${calendarSearchOpen?`<label class="planner-search"><span>⌕</span><input id="calendar-search" value="${esc(calendarQuery)}" placeholder="Search titles, tags and notes" aria-label="Search calendar"><button data-action="calendar-search" aria-label="Hide search">×</button></label>`:''}${organizationFilters('calendar')}${calendarView==='month'?monthCalendar(from):calendarView==='week'?weekCalendar(from):calendarView==='day'?dayCalendar(from):agendaCalendar(from,to)}</section>`;}
function eventButton(e,compact=false){const m=e.quest,color=eventColor(state,m),ink=readableColor(color,(page==='settings'&&draft?draft:state.settings.appearance).subtheme==='light'),start=new Date(e.at),skillNames=m.skills.map(id=>state.skills.find(s=>s.id===id)?.title).filter(Boolean);return `<div class="planner-event-wrap"><button class="calendar-event planner-event ${m.kind} ${m.status==='completed'&&!e.projected?'cleared':''}" style="--event-color:${color};--event-ink:${ink}" data-calendar-event="${esc(e.key)}"><span class="planner-event-time"><b>${timingLabel(e)}</b>${!compact?`<small>${timingMinutes(e)?timingMinutes(e)+' min':'No time slot'}</small>`:''}</span><span class="planner-event-body"><span class="planner-event-kind">${m.kind==='side'?'SIDE QUEST':'MAIN'}${e.projected?' · ↻ RECURRING':m.status==='completed'?' · ✓ COMPLETED':''}</span><b class="planner-event-title">${m.status==='completed'&&!e.projected?'<span class="completed-indicator" aria-label="Completed">✓</span>':''}${esc(m.title)}</b>${!compact?`<span class="planner-event-tags">${tagChips(m,3)}${m.tagIds.length>3?`<small>+${m.tagIds.length-3}</small>`:''}</span>${m.calendar.notes?`<span class="planner-event-note">${esc(m.calendar.notes.slice(0,160))}</span>`:''}${e.timing?.adjusted?'<span class="date-adjusted">Adjusted for this date</span>':''}${skillNames.length?`<span class="planner-event-skills">◈ ${skillNames.map(esc).join(' · ')}</span>`:''}`:''}</span><span class="planner-event-arrow">›</span></button><button class="event-edit-menu" data-event-edit="${esc(e.key)}" aria-label="Edit ${esc(m.title)}">⋮</button>${!compact&&(e.timing?.slots||[]).length?`<button class="event-date-edit" data-event-date-edit="${esc(e.key)}">Edit this date’s timeslots & deadline</button>`:''}</div>`;}
function monthCalendar(start){return `<div class="planner-month-layout"><div class="planner-month-panel"><div class="planner-weekdays">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="planner-dates">${Array.from({length:42},(_,i)=>{const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),events=calendarEntries.filter(e=>onDay(e,d));return `<button class="planner-date ${d.getMonth()!==calendarDate.getMonth()?'outside':''} ${localDay(d)===today()?'today':''} ${localDay(d)===localDay(calendarDate)?'selected':''}" data-calendar-select="${localDay(d)}" aria-label="${esc(d.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'}))}, ${events.length} events" aria-pressed="${localDay(d)===localDay(calendarDate)}"><b>${d.getDate()}</b><span class="planner-dots">${events.slice(0,3).map(e=>`<i style="background:${eventColor(state,e.quest)}"></i>`).join('')}${events.length>3?'<small>+</small>':''}</span></button>`;}).join('')}</div></div><div class="planner-selected-agenda">${selectedDayAgenda(calendarDate)}</div></div>`;}
function selectedDayAgenda(date){const events=calendarEntries.filter(e=>onDay(e,date));return `<div class="planner-agenda-heading"><div><span>${date.toLocaleDateString([],{weekday:'long'})}</span><h2>${date.toLocaleDateString([],{month:'long',day:'numeric'})}</h2></div><small>${events.length} ${events.length===1?'quest':'quests'}</small></div>${events.length?events.map(e=>eventButton(e)).join(''):`<div class="planner-empty"><span>▦</span><h3>No quests scheduled</h3><p>Choose another date or add a quest to this day.</p><button class="secondary" data-action="calendar-new">＋ Add quest</button></div>`}`;}
function weekCalendar(start){return `<div class="planner-week-strip">${Array.from({length:7},(_,i)=>{const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),events=calendarEntries.filter(e=>onDay(e,d));return `<button class="${localDay(d)===localDay(calendarDate)?'selected':''} ${localDay(d)===today()?'today':''}" data-calendar-select="${localDay(d)}"><span>${d.toLocaleDateString([],{weekday:'narrow'})}</span><b>${d.getDate()}</b><span class="planner-dots">${events.slice(0,2).map(e=>`<i style="background:${eventColor(state,e.quest)}"></i>`).join('')}</span></button>`;}).join('')}</div>${dayCalendar(calendarDate)}`;}

function dayCalendar(date){const events=calendarEntries.filter(e=>onDay(e,date)),allDay=events.filter(e=>!(e.timing?.slots||[]).length),timed=events.filter(e=>(e.timing?.slots||[]).length).flatMap(e=>e.timing.slots.map(slot=>({...e,displaySlot:slot}))).sort((a,b)=>eventStart(a)-eventStart(b)),base=new Date(localDay(date)+'T00:00:00'),ends=[],placed=[];for(const event of timed){const start=eventStart(event),end=eventEnd(event),s=start<base?0:start.getHours()*60+start.getMinutes(),t=localDay(end)!==localDay(base)?1440:end.getHours()*60+end.getMinutes();let lane=ends.findIndex(v=>v<=s);if(lane<0)lane=ends.length;ends[lane]=t;placed.push({event,start:s,end:Math.max(s+1,t),lane});}const lanes=Math.max(1,ends.length);return `<div class="day-calendar"><h3>${date.toLocaleDateString([],{weekday:'long',month:'long',day:'numeric'})}</h3>${allDay.length?`<div class="all-day-events"><span class="eyebrow">ANY TIME / ALL DAY</span>${allDay.map(e=>eventButton(e)).join('')}</div>`:''}<div class="day-timeline"><div class="day-hour-grid">${Array.from({length:24},(_,hour)=>`<div><span>${String(hour).padStart(2,'0')}:00</span></div>`).join('')}</div><div class="day-time-events">${placed.map(({event,start,end,lane})=>`<div class="timed-event-slot" style="top:${start}px;height:${Math.max(32,end-start)}px;left:${lane/lanes*100}%;width:${100/lanes}%">${eventButton(event,true)}</div>`).join('')}</div></div></div>`;}

function agendaCalendar(from,to){const days=[];for(const d=new Date(from);d<to;d.setDate(d.getDate()+1)){const items=calendarEntries.filter(e=>onDay(e,d));if(items.length)days.push(`<section class="planner-schedule-day"><button data-calendar-select="${localDay(d)}"><span>${d.toLocaleDateString([],{weekday:'short'})}</span><b>${d.getDate()}</b></button><div>${items.map(e=>eventButton(e)).join('')}</div></section>`);}return days.length?`<div class="planner-schedule">${days.join('')}</div>`:'<div class="planner-selected-agenda">'+selectedDayAgenda(calendarDate)+'</div>';}

function bindCalendar(){$$('[data-calendar-select]').forEach(b=>b.onclick=()=>{calendarDate=new Date(b.dataset.calendarSelect+'T12:00:00');if(calendarView==='agenda')calendarView='day';render();});$$('[data-action=calendar-date]').forEach(b=>b.onclick=openCalendarDate);$$('[data-calendar-view]').forEach(b=>b.onclick=()=>{calendarView=b.dataset.calendarView;render();});$$('[data-calendar-step]').forEach(b=>b.onclick=()=>{const n=+b.dataset.calendarStep;if(['month','agenda'].includes(calendarView)){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+n,1);}else calendarDate.setDate(calendarDate.getDate()+n*(calendarView==='week'?7:1));render();});$$('[data-calendar-today]').forEach(b=>b.onclick=()=>{calendarDate=new Date();render();});if($('#calendar-date'))$('#calendar-date').onchange=e=>{if(e.target.value){calendarDate=new Date(e.target.value+'T12:00:00');render();}};$$('[data-calendar-day]').forEach(b=>b.onclick=()=>{calendarDate=new Date(b.dataset.calendarDay+'T12:00:00');calendarView='day';render();});$$('[data-calendar-kind]').forEach(b=>b.onclick=()=>{calendarKind=b.dataset.calendarKind;render();});if($('#calendar-tag'))$('#calendar-tag').onchange=e=>{calendarTag=e.target.value;render();};if($('#calendar-completed'))$('#calendar-completed').onchange=e=>{calendarShowCompleted=e.target.checked;render();};if($('#calendar-search'))$('#calendar-search').oninput=e=>{calendarQuery=e.target.value;const at=e.target.selectionStart;render();$('#calendar-search').focus();$('#calendar-search').setSelectionRange(at,at);};$$('[data-calendar-event]').forEach(b=>b.onclick=()=>calendarDetails(b.dataset.calendarEvent));$$('[data-calendar-export]').forEach(b=>b.onclick=()=>{const quests=calendarExportQuests(state),format=b.dataset.calendarExport;download(format==='ics'?exportICS(quests):JSON.stringify({format:'daemon-calendar',version:3,tags:state.tags,quests},null,2),`daemon-calendar-${today()}.${format}`);});if($('#calendar-import'))$('#calendar-import').onchange=importCalendarFile;}
function calendarDetails(key){const event=calendarEntries.find(e=>e.key===key);if(event)showQuest(event.quest.id,event);}

async function importCalendarFile(e){try{const file=e.target.files[0];if(!file)return;if(file.size>4000000)throw Error('Calendar file limit: 4 MB.');const text=await file.text();let incoming,warnings=[],importedTagDefinitions=[];if(file.name.toLowerCase().endsWith('.json')||text.trim().startsWith('{')){const data=JSON.parse(text);if(data.format!=='daemon-calendar'||![1,2,3].includes(data.version)||!Array.isArray(data.quests)||data.quests.length>2000)throw Error('Choose Daemon Calendar JSON, or an .ics file.');importedTagDefinitions=data.tags||[];incoming=data.quests.map(m=>({...m,...(m.currencyVersion===2?{}:{coins:(m.coins||0)*100,currencyVersion:2}),calendar:{...m.calendar,enabled:true,uid:m.calendar?.uid||`${m.id}@daemon-deck.local`}}));}else{const parsed=importICS(text);warnings=parsed.warnings;incoming=parsed.events.map(event=>({...missionDefaults(),...event,repeat:event.recurrence.frequency,createdAt:new Date(Math.min(Date.now(),new Date(event.dueAt)-86400000)).toISOString(),calendar:event.calendar}));}const tagged=prepareCalendarTags(state,incoming,importedTagDefinitions);incoming=tagged.quests;const known=new Set(state.missions.filter(m=>m.calendar.enabled).map(m=>m.calendar.uid||`${m.id}@daemon-deck.local`)),map=new Map(),quests=[],importedOverrides=structuredClone(state.calendarOverrides);let skipped=0;for(const original of incoming){const id=original.calendar?.uid||`${original.title}:${original.dueAt}`;if(known.has(id)){skipped++;continue;}known.add(id);const sid=original.seriesId||id;if(!map.has(sid))map.set(sid,uid());if(original.dateOverrides)importedOverrides[map.get(sid)]=original.dateOverrides;quests.push({...original,id:uid(),seriesId:map.get(sid),parent:'',skills:[],repeatable:false,calendar:{...original.calendar,enabled:true,uid:id}});}const normalized=validate({...state,tags:tagged.tags,calendarOverrides:importedOverrides,missions:quests});quests.splice(0,quests.length,...normalized.missions);const modal=$('#editor');modal.className='';modal.innerHTML=`<div class="modal-heading"><h2>Import calendar?</h2><button class="close" data-close aria-label="Close">×</button></div><p>${quests.length} quests to add / ${skipped} duplicates skipped.</p><p class="fine-print">Local quests and progress are preserved. Imported events become opted-in quests and can schedule future deadline alarms. Import does not award XP, credits, or change skills.</p>${warnings.length?`<p>${esc([...new Set(warnings)].join(' '))}</p>`:''}<div class="import-preview">${quests.slice(0,20).map(m=>`<div><span class="tag">${m.kind==='side'?'Side Quest':'Main'}</span><b>${esc(m.title)}</b><small>${esc(fmt(effectiveDeadline(state,m)))}</small></div>`).join('')}</div><div class="modal-actions"><button class="secondary" data-close>Cancel</button><button class="primary" id="confirm-calendar-import" ${!quests.length?'disabled':''}>Import ${quests.length} quests</button></div>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());$('#confirm-calendar-import').onclick=()=>{if(mutate(()=>{state.tags=tagged.tags;state.calendarOverrides=importedOverrides;state.missions.push(...quests);})){modal.close();render();toast('CALENDAR IMPORTED');}};modal.showModal();}catch(e){toast(e.message||'Calendar import failed.');}}
function orderedTags(){return state.tags.filter(t=>!t.parentId).sort((a,b)=>a.name.localeCompare(b.name)).flatMap(t=>[t,...state.tags.filter(c=>c.parentId===t.id).sort((a,b)=>a.name.localeCompare(b.name))]);}
function tagChips(item,limit=30,missionLabel=false){const light=state.settings.appearance.subtheme==='light';return itemTags(state,item).slice(0,limit).map(t=>`<span class="stable-tag ${t.parentId?'subtag':''}" style="--tag-color:${t.color};--tag-ink:${readableColor(t.color,light)}"><i></i>${esc(missionLabel&&t.id==='daemon:main'?'Main':tagPath(state.tags,t))}</span>`).join('');}
function tagOptions(selected){return orderedTags().filter(t=>manualTags(state).some(v=>v.id===t.id)).map(t=>`<label class="tag-choice"><input type="checkbox" name="tagIds" value="${t.id}" ${selected.includes(t.id)?'checked':''}><i style="background:${t.color}"></i><span>${esc(tagPath(state.tags,t))}</span></label>`).join('')||'<p class="muted">No manual tags yet. Create one below, or use Attributes → Add tags.</p>';}

function tagSelector(x){return `<fieldset class="tag-picker"><legend>Tags / choose multiple</legend><div id="tag-options">${tagOptions(x.tagIds||[])}</div><label class="field">Title color from tag<select name="primaryTagId">${(x.tagIds||[]).length?itemTags(state,x).map(t=>`<option value="${t.id}" ${x.primaryTagId===t.id?'selected':''}>${esc(tagPath(state.tags,t))}</option>`).join(''):'<option value="">Untagged / use assigned quest color</option>'}</select></label><details class="inline-tag-creator"><summary>＋ Create a reusable tag</summary>${field('Tag name','inlineTagName','','text','maxlength="60"')}<label class="field">Tag color<input type="color" name="inlineTagColor" value="${pickColor(state.settings.calendar.palette)}"></label><label class="check-label"><input type="checkbox" name="inlineIsSub"> Subtag / belongs to a tag</label>${select('Parent tag','inlineTagParent',manualTags(state).filter(t=>!t.parentId).map(t=>[t.id,t.name]),'')}<button type="button" class="secondary full" data-inline-create-tag>Create tag</button><p class="fine-print">Tags are shared across quests, Attributes, Skills, and Calendar. A primary tag controls the event title color.</p></details></fieldset>`;}
function bindTagSelector(x){const primary=$('[name=primaryTagId]'),effective=()=>({...x,tagIds:$$('[name=tagIds]:checked').map(i=>i.value),skills:$$('[name=skills]:checked').map(i=>i.value)}),update=()=>{const item=effective(),previous=primary.value,tags=itemTags(state,item);primary.innerHTML='<option value="">Default / paired tag or quest color</option>'+(tags.length?tags.map(t=>`<option value="${t.id}" ${previous===t.id?'selected':''}>${esc(tagPath(state.tags,t))}</option>`).join(''):'');if(tags.some(t=>t.id===previous))primary.value=previous;else primary.value=item.tagIds[0]||linkedEntities(state,item)[0]?.boundTagId||'';const auto=$('[data-auto-tags]');if(auto)auto.innerHTML=itemTags(state,{...item,tagIds:[]}).map(t=>`<span class="stable-tag" style="--tag-color:${t.color};--tag-ink:${readableColor(t.color,state.settings.appearance.subtheme==='light')}"><i></i>${esc(t.name)}</span>`).join('');},wire=()=>{$$('[name=tagIds],[name=skills]').forEach(input=>input.addEventListener('change',update));};wire();update();const sub=$('[name=inlineIsSub]'),parent=$('[name=inlineTagParent]'),color=$('[name=inlineTagColor]');if(!sub)return;parent.disabled=!sub.checked;sub.onchange=()=>{parent.disabled=!sub.checked;if(sub.checked&&parent.value)color.value=state.tags.find(t=>t.id===parent.value).color;};parent.onchange=()=>{if(sub.checked&&parent.value)color.value=state.tags.find(t=>t.id===parent.value).color;};$('[data-inline-create-tag]').onclick=()=>{const name=$('[name=inlineTagName]').value.trim(),parentId=sub.checked?parent.value:'';if(!name){toast('Give the tag a name.');return;}if(sub.checked&&!parentId){toast('Create a main tag first.');return;}const t={id:uid(),name,parentId,color:color.value},selected=$$('[name=tagIds]:checked').map(i=>i.value);if(mutate(()=>state.tags.push(t))){$('#tag-options').innerHTML=tagOptions([...selected,t.id]);$('[name=inlineTagName]').value='';if($('#editor-error'))$('#editor-error').textContent='';parent.innerHTML=manualTags(state).filter(t=>!t.parentId).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');wire();update();primary.value=t.id;}};}

function openTagManager(editId=''){if(isSystemTag(editId)){toast('Main Mission and Side Quest tags are fixed.');return;}const t=state.tags.find(t=>t.id===editId),modal=$('#editor');modal.className='tag-manager-dialog';modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">SHARED ORGANIZATION</span><h2>Tags & subtags</h2></div><button class="close" data-close aria-label="Close">×</button></div><p class="muted">Reusable tags replace categories. Select several on a quest; its primary tag supplies the Calendar title color. Filtering a parent includes its subtags.</p><form id="tag-form"><h3>${t?'Edit tag':'Add tag'}</h3>${field('Tag name','tagName',t?.name||'','text','required maxlength="60"')}<div class="tag-form-row"><label class="field">Color<input type="color" name="tagColor" value="${t?.color||pickColor(state.settings.calendar.palette)}"></label><label class="check-label"><input type="checkbox" name="isSub" ${t?.parentId?'checked':''}> Subtag</label></div>${select('Parent tag','tagParent',state.tags.filter(p=>!p.parentId&&p.id!==editId&&!isSystemTag(p.id)).map(p=>[p.id,p.name]),t?.parentId||'')}<div class="tag-form-actions"><button class="primary" type="submit">${t?'Save tag':'Create tag'}</button>${t?`<button type="button" class="secondary" data-new-tag>New tag</button><button type="button" class="danger" data-delete-tag ${lockedTag(state,t.id)||state.tags.some(c=>c.parentId===t.id&&lockedTag(state,c.id))?'disabled':''}>Delete tag</button>`:''}</div>${t&&tagOwners(state,t.id).length?`<p class="fine-print">Paired with ${tagOwners(state,t.id).map(e=>esc(e.title)).join(', ')}. Move every pairing in its Attribute or Skill editor before deleting this tag.</p>`:''}<p id="editor-error" class="form-error" role="alert"></p></form><div class="tag-catalog">${orderedTags().map(tag=>{const count=[...state.missions,...state.skills,...state.rewards].filter(item=>itemTags(state,item).some(t=>t.id===tag.id)).length;return `<button class="tag-catalog-row ${tag.parentId?'child':''}" data-tag-edit="${tag.id}" ${isSystemTag(tag.id)?'disabled':''}><i style="background:${tag.color}"></i><span><b>${esc(tag.name)}</b><small>${isSystemTag(tag.id)?'Fixed quest tag':tagOwners(state,tag.id).length?'Paired / '+tagOwners(state,tag.id).map(e=>esc(e.title)).join(', '):tag.parentId?esc(state.tags.find(p=>p.id===tag.parentId).name)+' / subtag':'Manual tag'} · ${count} assignments</small></span><span>›</span></button>`;}).join('')||'<div class="planner-empty"><h3>No tags yet</h3><p>Create your first tag above.</p></div>'}</div>`;modal.querySelector('[data-close]').onclick=()=>{modal.close();render();};const sub=$('[name=isSub]'),parent=$('[name=tagParent]'),color=$('[name=tagColor]');parent.disabled=!sub.checked;sub.onchange=()=>{parent.disabled=!sub.checked;if(sub.checked&&parent.value&&!t)color.value=state.tags.find(t=>t.id===parent.value).color;};parent.onchange=()=>{if(sub.checked&&!t)color.value=state.tags.find(t=>t.id===parent.value).color;};$('#tag-form').onsubmit=e=>{e.preventDefault();const name=$('[name=tagName]').value.trim(),parentId=sub.checked?parent.value:'';if(sub.checked&&!parentId){toast('Select a parent tag.');return;}if(t&&sub.checked&&state.tags.some(c=>c.parentId===t.id)){toast('Move or delete this tag’s subtags before making it a subtag.');return;}if(mutate(()=>{const value={...t,id:t?.id||uid(),name,color:color.value,parentId};if(t&&t.name!==name)delete value.generatedFor;if(t)state.tags=state.tags.map(tag=>tag.id===t.id?value:tag);else state.tags.push(value);})){render();openTagManager();}};$$('[data-tag-edit]').forEach(b=>b.onclick=()=>openTagManager(b.dataset.tagEdit));if($('[data-new-tag]'))$('[data-new-tag]').onclick=()=>openTagManager();if($('[data-delete-tag]'))$('[data-delete-tag]').onclick=()=>{if(confirm('Delete this tag and its subtags? Quests, skills and progress are kept.'))if(mutate(()=>deleteTag(state,t.id))){orgFilters.calendar.tags=orgFilters.calendar.tags.filter(id=>state.tags.some(t=>t.id===id));render();openTagManager();}};if(!modal.open)modal.showModal();}
function calendarColorSettings(){return `<section class="panel calendar-color-settings"><div class="panel-title"><h2>Calendar colors & tags</h2><button class="secondary" data-action="manage-tags">Add tags</button></div><p class="muted">Tagged quests use their primary tag’s color. Quests without a manual or paired tag receive a saved color from this palette. Changing a tag color updates every linked event. Text shades adjust for contrast.</p><div class="calendar-palette">${state.settings.calendar.palette.map((c,i)=>`<div><label><span class="sr-only">Palette color ${i+1}</span><input type="color" value="${c}" data-palette-color="${i}"></label><button class="text-button" data-palette-remove="${i}" aria-label="Remove palette color ${i+1}" ${state.settings.calendar.palette.length<=2?'disabled':''}>×</button></div>`).join('')}</div><div class="palette-add"><label>New color<input type="color" id="new-palette-color" value="${pickColor(defaultPalette)}"></label><button class="secondary" data-palette-add ${state.settings.calendar.palette.length>=32?'disabled':''}>＋ Add color</button></div><button class="secondary full" data-palette-shuffle>Shuffle untagged quest colors</button><details class="mission-color-list"><summary>Individual quest colors</summary>${state.missions.filter(m=>m.status==='active').map(m=>{const colorTag=itemTags(state,m).find(t=>t.id===m.primaryTagId)||itemTags(state,m).find(t=>!isSystemTag(t.id));return `<label><span><b>${esc(m.title)}</b><small>${colorTag?'Uses '+esc(tagPath(state.tags,colorTag)):'Assigned quest color'}</small></span><input type="color" data-quest-color="${m.id}" value="${eventColor(state,m)}" ${colorTag?'disabled':''}></label>`;}).join('')||'<p class="muted">No active quests.</p>'}</details></section>`;}
function bindTagSettings(){$$('[data-palette-color]').forEach(input=>input.onchange=()=>{mutate(()=>state.settings.calendar.palette[+input.dataset.paletteColor]=input.value);render();});$$('[data-palette-remove]').forEach(b=>b.onclick=()=>{mutate(()=>state.settings.calendar.palette.splice(+b.dataset.paletteRemove,1));render();});if($('[data-palette-add]'))$('[data-palette-add]').onclick=()=>{mutate(()=>state.settings.calendar.palette.push($('#new-palette-color').value));render();};if($('[data-palette-shuffle]'))$('[data-palette-shuffle]').onclick=()=>{mutate(()=>{const used=[];for(const m of state.missions.filter(m=>!itemTags(state,m).some(t=>!isSystemTag(t.id)))){m.calendar.color=pickColor(state.settings.calendar.palette,used);m.calendar.colorAssigned=true;used.push(m.calendar.color);}});render();};$$('[data-quest-color]').forEach(input=>input.onchange=()=>{mutate(()=>{const m=state.missions.find(m=>m.id===input.dataset.questColor);m.calendar.color=input.value;m.calendar.colorAssigned=true;});render();});}
function calendarSheet(title,content){const modal=$('#editor');modal.className='calendar-sheet';modal.innerHTML=`<div class="sheet-handle"></div><div class="modal-heading"><h2>${title}</h2><button class="close" data-close aria-label="Close">×</button></div>${content}`;modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();return modal;}
function calendarViewPicker(){const descriptions={month:'Month grid and selected-day agenda',week:'Seven-day strip and hourly timeline',day:'Full day timeline with overlapping events',agenda:'Chronological schedule for the month'},modal=calendarSheet('Calendar view',`<div class="planner-view-list">${['month','week','day','agenda'].map(view=>`<button data-pick-calendar-view="${view}" class="${calendarView===view?'selected':''}"><span>${{month:'▦',week:'▤',day:'◷',agenda:'☷'}[view]}</span><span><b>${view==='agenda'?'Schedule':view[0].toUpperCase()+view.slice(1)}</b><small>${descriptions[view]}</small></span><span>${calendarView===view?'✓':''}</span></button>`).join('')}</div>`);modal.querySelectorAll('[data-pick-calendar-view]').forEach(b=>b.onclick=()=>{calendarView=b.dataset.pickCalendarView;modal.close();render();});}
