function calendarTools(){const modal=calendarSheet('Calendar tools',`<section class="planner-tool-section"><h3>Calendar visibility</h3><p class="muted">Use the Attributes, Skills and Tags controls on Calendar to combine filters. Main Mission and Side Quest are fixed tags.</p><label class="check-label"><input id="calendar-completed" type="checkbox" ${calendarShowCompleted?'checked':''}> Show completed quests</label><div class="calendar-tool-actions"><button class="secondary" data-calendar-clear-filters>Reset all filters</button><button class="primary" data-calendar-apply-filters>Apply</button></div></section><section class="planner-tool-section"><h3>Calendar files</h3><p class="muted">Export opted-in quests, or preview a file import. Your progress stays on this device.</p><div class="calendar-io-actions"><button class="secondary" data-calendar-export="ics">↓ Export .ics</button><button class="secondary" data-calendar-export="json">↓ Export JSON</button><label class="file-button">↑ Import calendar<input id="calendar-import" type="file" accept=".ics,.json,text/calendar,application/json"></label></div></section><button class="text-button full" data-calendar-settings>Calendar colors, tags & retention in Config ↗</button>`);bindCalendar();$('#calendar-completed').onchange=()=>{};modal.querySelector('[data-calendar-apply-filters]').onclick=()=>{calendarShowCompleted=$('#calendar-completed').checked;modal.close();render();};modal.querySelector('[data-calendar-clear-filters]').onclick=()=>{orgFilters.calendar={attributes:[],skills:[],tags:[],match:'any'};calendarQuery='';calendarShowCompleted=true;modal.close();render();};modal.querySelector('[data-calendar-settings]').onclick=()=>{modal.close();go('settings');$('.calendar-color-settings')?.scrollIntoView({block:'start'});};}

function timingLabel(e){const t=e.timing||occurrenceTiming(state,e.quest,e.originalAt||e.at),slots=e.displaySlot?[e.displaySlot]:t.slots;return slots.length?slots.map(s=>`${s.start}–${s.end}`).join(' / '):t.allDay?'All day':'Any time';}
