function slotFields(slots){return `<fieldset class="slot-picker"><legend>Time slots / optional</legend><p class="muted">Reserve hours on this occurrence’s day. Leave blank to show the quest in Any time. Add up to eight non-overlapping slots.</p><div data-slot-list>${slots.map(s=>slotRow(s)).join('')}</div><button class="secondary" type="button" data-add-slot>＋ Add time slot</button></fieldset>`;}
