function slotsFromForm(f){const starts=f.getAll('slotStart'),ends=f.getAll('slotEnd'),slots=starts.map((start,i)=>({start,end:ends[i]})).filter(s=>s.start||s.end);validateSlots(slots);return slots.sort((a,b)=>a.start.localeCompare(b.start));}
function bindSlots(root){const wire=()=>root.querySelectorAll('[data-remove-slot]').forEach(b=>b.onclick=()=>b.closest('.time-slot-row').remove());wire();const add=root.querySelector('[data-add-slot]');if(add)add.onclick=()=>{if(root.querySelectorAll('.time-slot-row').length>=8){toast('Use up to eight time slots.');return;}root.querySelector('[data-slot-list]').insertAdjacentHTML('beforeend',slotRow());wire();};const allDay=root.querySelector('[name=calAllDay]');if(allDay){const update=()=>{const picker=root.querySelector('.slot-picker');if(!picker)return;picker.disabled=allDay.checked;picker.classList.toggle('disabled',allDay.checked);};allDay.addEventListener('change',update);update();}}
function setupCreator(){const form=$('#item-form'),modal=$('#editor');form.noValidate=true;modal.classList.add('quest-creator');const header=form.querySelector('.modal-heading'),error=form.querySelector('#editor-error'),footer=form.querySelector('.modal-actions'),nodes=[...form.children].filter(n=>![header,error,footer].includes(n)),tabs=[['basics','Quest'],['schedule','Schedule'],['rewards','Rewards'],['customize','Customize']],panels=Object.fromEntries(tabs.map(([id])=>{const p=document.createElement('section');p.dataset.creatorPanel=id;p.id='creator-'+id;p.className='creator-panel';p.hidden=id!=='basics';return [id,p];}));for(const node of nodes){let group='customize';if(node.matches('.quest-type-banner,.setting,[data-mission-alerts]')||node.querySelector('[name=dueAt],[name=calEnabled]'))group='schedule';else if(node.querySelector('[name=friction],[name=coins],[name=skills]'))group='rewards';else if(node.querySelector('[name=title],[name=description],[name=steps],[name=notes],[name=stepdone]'))group='basics';panels[group].append(node);}const orgFilters={missions:{attributes:[],skills:[],tags:[],match:'any'},calendar:{attributes:[],skills:[],tags:[],match:'any'}},orgOpen=new Set();
const nav=document.createElement('nav');nav.className='creator-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','Quest editor sections');nav.innerHTML=tabs.map(([id,label])=>`<button type="button" role="tab" data-creator-tab="${id}" aria-controls="creator-${id}" aria-selected="${id==='basics'}">${label}</button>`).join('');header.after(nav);nav.after(...Object.values(panels));const heading=document.createElement('div');heading.className='creator-heading';header.before(heading);heading.append(header,nav);form.append(error,footer);nav.querySelectorAll('[data-creator-tab]').forEach(b=>b.onclick=()=>showCreatorTab(b.dataset.creatorTab));form.querySelector('[name=title]').focus();}
function showCreatorTab(id){$$('[data-creator-panel]').forEach(p=>p.hidden=p.dataset.creatorPanel!==id);$$('[data-creator-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.creatorTab===id));b.tabIndex=b.dataset.creatorTab===id?0:-1;});$('#editor').scrollTo({top:0,behavior:'instant'});}
function validateCreator(form){const invalid=[...form.elements].find(e=>!e.disabled&&typeof e.checkValidity==='function'&&!e.checkValidity());if(!invalid)return true;const panel=invalid.closest('[data-creator-panel]');if(panel)showCreatorTab(panel.dataset.creatorPanel);for(let p=invalid.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;invalid.reportValidity();return false;}
function bindQuestTaps(){$$('[data-event-date-edit]').forEach(b=>b.onclick=()=>{const e=calendarEntries.find(e=>e.key===b.dataset.eventDateEdit);if(e)editDateOverride(e.quest,e.originalAt||e.at,e);});const longPress=(node,edit)=>{let timer,startX,startY,held=false;node.addEventListener('pointerdown',e=>{if(e.button!==0)return;held=false;startX=e.clientX;startY=e.clientY;timer=setTimeout(()=>{held=true;edit();},550);});const cancel=()=>clearTimeout(timer);node.addEventListener('pointermove',e=>{if(Math.hypot(e.clientX-startX,e.clientY-startY)>10)cancel();});node.addEventListener('pointerup',cancel);node.addEventListener('pointercancel',cancel);node.addEventListener('contextmenu',e=>{e.preventDefault();cancel();if(!held){held=true;edit();}});node.addEventListener('click',e=>{if(held){e.preventDefault();e.stopImmediatePropagation();held=false;}},true);};$$('[data-quest]').forEach(b=>{b.onclick=()=>showQuest(b.dataset.quest);longPress(b,()=>openEditor('mission',b.dataset.quest));});$$('[data-calendar-event]').forEach(b=>longPress(b,()=>{const e=calendarEntries.find(e=>e.key===b.dataset.calendarEvent);if(e)openEditor('mission',e.quest.id);}));$$('[data-event-edit]').forEach(b=>b.onclick=()=>{const e=calendarEntries.find(e=>e.key===b.dataset.eventEdit);if(e)openEditor('mission',e.quest.id);});}
function showQuest(id,event=null){const m=state.missions.find(m=>m.id===id);if(!m)return;const originalAt=event?.originalAt||m.dueAt,t=occurrenceTiming(state,m,originalAt),projected=!!event?.projected,children=state.missions.filter(c=>c.parent===id),modal=$('#editor');modal.className='quest-detail';modal.innerHTML=`<div class="modal-heading"><div><span class="eyebrow">${m.kind==='side'?'SIDE QUEST':'MAIN MISSION'} / ${projected?'PROJECTED OCCURRENCE':m.status.toUpperCase()}</span></div><div class="detail-header-actions"><button class="more" data-detail-edit aria-label="Edit ${esc(m.title)}">⋮</button><button class="close" data-close aria-label="Close">×</button></div></div><div class="detail-title">${art(m)}<h2>${esc(m.title)}</h2></div>${m.description?`<p class="detail-description">${esc(m.description)}</p>`:''}<div class="detail-tags">${tagChips(m)}</div><div class="detail-facts"><div><small>Deadline</small><b>${m.repeatable?'None / repeatable':esc(fmt(t.deadline))}</b>${t.adjusted?'<span>Adjusted for this date</span>':''}</div><div><small>Time slots</small><b>${m.repeatable?'Any time':esc(timingLabel({quest:m,timing:t}))}</b></div><div><small>Payout</small><b>${xpFor(m)} XP / ${coinsFor(m).toLocaleString()} €$</b></div><div><small>Schedule</small><b>${esc(recurrenceLabel(m))}</b></div><div><small>Effort estimate</small><b>${m.duration} min</b></div></div><section class="detail-section"><div class="panel-title"><h3>Subtasks</h3><span>${projected?0:m.subtasks.filter(s=>s.done).length} / ${m.subtasks.length}</span></div>${m.subtasks.length?m.subtasks.map((task,i)=>`<label class="detail-step"><input type="checkbox" data-detail-step="${i}" ${!projected&&task.done?'checked':''} ${projected||m.status!=='active'?'disabled':''}><span>${esc(task.title)}</span></label>`).join(''):'<p class="muted">No subtasks.</p>'}${projected?'<p class="fine-print">Subtasks and notes come from the current quest template. A projected occurrence has no completion progress yet.</p>':''}${!projected&&children.length?`<h3>Child missions</h3>${children.map(c=>`<button class="detail-child" data-detail-child="${c.id}"><span>${c.status==='completed'?'✓':'○'}</span>${esc(c.title)}<span>›</span></button>`).join('')}`:''}</section><section class="detail-section"><h3>Private notes</h3><div class="detail-notes">${esc(m.notes||'No private notes.')}</div></section>${m.calendar.enabled?`<section class="detail-section"><h3>Calendar notes</h3><div class="detail-notes">${esc(m.calendar.notes||'No calendar notes.')}</div></section>`:''}${m.skills.length?`<section class="detail-section"><h3>Attributes & Skills</h3><div class="detail-tags">${m.skills.map(id=>state.skills.find(s=>s.id===id)).filter(Boolean).map(s=>`<span class="tag">${esc(s.title)} / LVL ${level(s.xp)}</span>`).join('')}</div></section>`:''}${m.location?`<section class="detail-section"><h3>Location</h3><p>${esc(m.location)}</p></section>`:''}<div class="detail-actions">${m.calendar.enabled&&!m.repeatable?'<button class="secondary full" data-edit-date>Edit this specific date’s Timeslots & Deadline</button>':''}${!projected&&m.status==='active'?'<button class="primary full" data-detail-complete>Complete quest</button>':''}<p class="fine-print">Use ⋮ or long press a quest card to edit all quest settings.${projected?' Editing the quest changes the series; the date-specific button changes only this occurrence.':''}</p></div>`;modal.querySelector('[data-close]').onclick=()=>modal.close();modal.querySelector('[data-detail-edit]').onclick=()=>openEditor('mission',id);modal.querySelectorAll('[data-detail-step]').forEach(input=>input.onchange=()=>{const scroll=modal.scrollTop;if(mutate(()=>state.missions.find(m=>m.id===id).subtasks[+input.dataset.detailStep].done=input.checked)){render();showQuest(id,event);modal.scrollTop=scroll;}});modal.querySelectorAll('[data-detail-child]').forEach(b=>b.onclick=()=>showQuest(b.dataset.detailChild));if(modal.querySelector('[data-detail-complete]'))modal.querySelector('[data-detail-complete]').onclick=()=>confirmCompletion(id);if(modal.querySelector('[data-edit-date]'))modal.querySelector('[data-edit-date]').onclick=()=>editDateOverride(m,originalAt,event);if(!modal.open)modal.showModal();}
function editDateOverride(m,originalAt,event){const t=occurrenceTiming(state,m,originalAt),existing=state.calendarOverrides[m.seriesId]?.[t.overrideKey],modal=$('#editor');modal.className='date-override-editor';modal.innerHTML=`<form id="date-override-form" novalidate><div class="modal-heading"><div><span class="eyebrow">ONLY THIS OCCURRENCE / ${esc(t.originalDay)}</span><h2>Timeslots & deadline</h2></div><button class="close" type="button" data-override-back aria-label="Back to quest">×</button></div><h3>${esc(m.title)}</h3><p class="muted">The rest of the series keeps its original deadline and slots. Changing the date moves only this occurrence.</p>${field('This date’s deadline','overrideDeadline',localDateTime(t.deadline),'datetime-local','required')}<label class="check-label"><input type="checkbox" name="calAllDay" ${t.allDay?'checked':''}> All-day / no time blocks</label>${slotFields(t.slots)}<p class="fine-print">Deadline pre-reminders are redistributed only when this actual occurrence’s deadline changes. Future projected dates become actual quests on completion of the previous quest.</p><div id="editor-error" class="form-error" role="alert"></div><div class="modal-actions">${existing?'<button class="danger" type="button" data-reset-date>Reset this date to series default</button>':''}<span></span><button class="secondary" type="button" data-override-back>Cancel</button><button class="primary" type="submit">Save this date</button></div></form>`;bindSlots(modal);modal.querySelectorAll('[data-override-back]').forEach(b=>b.onclick=()=>showQuest(m.id,event));const refresh=()=>{render();showQuest(m.id,{...event,originalAt,projected:event?.projected||false});};$('#date-override-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),deadline=new Date(f.get('overrideDeadline')).toISOString(),slots=f.has('calAllDay')?[]:slotsFromForm(f);if(mutate(()=>{state.calendarOverrides[m.seriesId]??={};state.calendarOverrides[m.seriesId][t.overrideKey]={originalAt,deadline,slots,allDay:f.has('calAllDay')};})){calendarDate=new Date(deadline);refresh();}}catch(e){$('#editor-error').textContent=e.message;}};if(modal.querySelector('[data-reset-date]'))modal.querySelector('[data-reset-date]').onclick=()=>{if(mutate(()=>{delete state.calendarOverrides[m.seriesId][t.overrideKey];if(!Object.keys(state.calendarOverrides[m.seriesId]).length)delete state.calendarOverrides[m.seriesId];}))refresh();};}

