function entityTagFields(old){return `<section class="editor-section entity-tag-section"><h3>Paired tag / required</h3><p class="fine-print">A tag named after this ${old?.parentId||!old&&newSkillParent?'Skill':'Attribute'} is created automatically. Pair another tag here to move the link. Paired tags are only applied by selecting their Attribute or Skill on a quest.</p>${select('Paired tag','boundTagId',[['','Automatic / use this name'],...orderedTags().filter(t=>!isSystemTag(t.id)).map(t=>[t.id,tagPath(state.tags,t)])],old?.boundTagId||'')}</section>`;}
function organizationFilters(scope){const f=orgFilters[scope],groups=[['attributes','Attributes',state.skills.filter(e=>!e.parentId).map(e=>({id:e.id,name:e.title,color:state.tags.find(t=>t.id===e.boundTagId)?.color}))],['skills','Skills',state.skills.filter(e=>e.parentId).map(e=>({id:e.id,name:(state.skills.find(p=>p.id===e.parentId)?.title||'')+' / '+e.title,color:state.tags.find(t=>t.id===e.boundTagId)?.color}))],['tags','Tags',orderedTags().filter(t=>!tagOwners(state,t.id).length).map(t=>({...t,name:tagPath(state.tags,t)}))]],count=groups.reduce((n,[key])=>n+f[key].length,0);return `<section class="organization-filters" data-org-scope="${scope}" aria-label="Filter by Attributes, Skills and tags"><div class="org-filter-groups">${groups.map(([key,label,items])=>`<details class="org-filter-group" data-org-group="${key}" ${orgOpen.has(scope+':'+key)?'open':''}><summary>${label}<span>${f[key].length||'All'}</span><b>⌄</b></summary><div class="org-filter-options">${items.map(item=>`<label class="org-filter-chip"><input type="checkbox" data-org-filter="${key}" value="${item.id}" ${f[key].includes(item.id)?'checked':''}><span class="org-filter-check" aria-hidden="true">✓</span><i style="background:${item.color}"></i><span>${esc(item.name)}</span></label>`).join('')||`<p class="muted">No ${label.toLowerCase()} yet.</p>`}${key==='tags'?`<label class="field org-match">Match selected tags<select data-org-match="${scope}"><option value="any" ${f.match==='any'?'selected':''}>Any selected tag</option><option value="all" ${f.match==='all'?'selected':''}>All selected tags</option></select></label>`:''}<button class="secondary full" type="button" data-close-org>Done</button></div></details>`).join('')}</div>${count?`<div class="org-filter-status"><span>${count} selected · match within each group</span><button class="text-button" data-clear-organization="${scope}">Reset filters ×</button></div>`:''}<p class="org-filter-hint">Combine groups to narrow results. Select multiple options in each group.</p></section>`;}
function bindOrganizationFilters(){$$('[data-org-scope]').forEach(root=>{const scope=root.dataset.orgScope;root.querySelectorAll('[data-org-group]').forEach(d=>d.ontoggle=()=>{const key=scope+':'+d.dataset.orgGroup;if(!d.isConnected)return;if(d.open){orgOpen.add(key);root.querySelectorAll('[data-org-group]').forEach(other=>{if(other!==d){other.open=false;orgOpen.delete(scope+':'+other.dataset.orgGroup);}});}else orgOpen.delete(key);});root.querySelectorAll('[data-org-match]').forEach(input=>input.onchange=()=>{orgFilters[scope].match=input.value;render();});root.querySelectorAll('[data-close-org]').forEach(b=>b.onclick=()=>{b.closest('details').open=false;});root.querySelectorAll('[data-org-filter]').forEach(input=>input.onchange=()=>{root.querySelectorAll('[data-org-group]').forEach(d=>{const key=scope+':'+d.dataset.orgGroup;if(d.open)orgOpen.add(key);else orgOpen.delete(key);});orgFilters[scope][input.dataset.orgFilter]=[...root.querySelectorAll(`[data-org-filter="${input.dataset.orgFilter}"]:checked`)].map(i=>i.value);render();});});$$('[data-clear-organization]').forEach(b=>b.onclick=()=>{orgFilters[b.dataset.clearOrganization]={attributes:[],skills:[],tags:[],match:'any'};render();});}
function retentionSettings(){const c=state.settings.calendar;return `<section class="panel retention-settings"><h2>Completed Calendar history</h2><p>Completed quests stay in Calendar with a check mark. Cleanup is off by default.</p><label class="setting">Automatically delete old completed Calendar quests<input type="checkbox" id="calendar-auto-delete" ${c.autoDelete?'checked':''}></label><label class="field">Delete after <output id="retention-years-value">${c.retentionYears} years</output><input type="range" id="calendar-retention-years" min="1" max="8" step="1" value="${c.retentionYears}"></label><p class="fine-print">${c.autoDelete?'Cleanup is enabled.':'Cleanup is disabled.'} Age is measured from each quest’s creation date. Only completed, Calendar-opted quests are removed, when the app next opens or saves. Earned XP, credits, Attributes, Skills and the activity log are kept.</p></section>`;}
function bindRetention(){if($('#calendar-retention-years'))$('#calendar-retention-years').oninput=e=>{$('#retention-years-value').value=e.target.value+' years';};if($('#calendar-retention-years'))$('#calendar-retention-years').onchange=e=>{const years=+e.target.value;if(mutate(()=>state.settings.calendar.retentionYears=years))render();};if($('#calendar-auto-delete'))$('#calendar-auto-delete').onchange=e=>{const enabled=e.target.checked;if(mutate(()=>state.settings.calendar.autoDelete=enabled))render();};}

// One delegated gesture handler survives app renders and keeps editor drafts intact.
function installTabSwipes(){
 let gesture=null;
 const ignored=target=>{if(target.closest('input,textarea,select,[contenteditable],.mobile-nav,.creator-tabs,.icon-picker,.day-timeline,.description-trigger,.description-popup'))return true;for(let el=target;el&&el!==document.body;el=el.parentElement){if(el.scrollWidth>el.clientWidth+8&&/auto|scroll/.test(getComputedStyle(el).overflowX))return true;}return false;};
 document.addEventListener('touchstart',e=>{gesture=null;if(document.querySelector('.reward-panel[open]')||e.touches.length!==1||ignored(e.target))return;const modal=$('#editor');if(modal.open&&!modal.classList.contains('quest-creator'))return;const t=e.touches[0];gesture={x:t.clientX,y:t.clientY,at:Date.now(),editor:modal.open};},{passive:true});
 document.addEventListener('touchmove',e=>{if(!gesture)return;if(e.touches.length!==1){gesture=null;return;}const dx=e.touches[0].clientX-gesture.x,dy=e.touches[0].clientY-gesture.y;if(Math.abs(dy)>35&&Math.abs(dy)>Math.abs(dx)){gesture=null;return;}if(Math.abs(dx)>20&&Math.abs(dx)>Math.abs(dy)*1.5)e.preventDefault();},{passive:false});
 document.addEventListener('touchcancel',()=>gesture=null,{passive:true});
 document.addEventListener('touchend',e=>{const g=gesture;gesture=null;if(!g||!e.changedTouches.length||Date.now()-g.at>900)return;const dx=e.changedTouches[0].clientX-g.x,dy=e.changedTouches[0].clientY-g.y;if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.5)return;const modal=$('#editor');if(modal.open!==g.editor)return;const step=dx<0?1:-1;if(g.editor){const buttons=$$('[data-creator-tab]'),index=buttons.findIndex(b=>b.getAttribute('aria-selected')==='true'),next=buttons[index+step];if(next)showCreatorTab(next.dataset.creatorTab);}else {const visible=nav.filter(n=>n[0]!=='journal'),index=visible.findIndex(n=>n[0]===page),next=visible[index+step];if(next)go(next[0]);}},{passive:true});
}
installTabSwipes();

function assignmentChoice(entity,mission){return `<label class="skill-check xp-choice ${entity.parentId?'xp-skill':'xp-attribute'}"><input type="checkbox" name="skills" value="${entity.id}" data-attribute-parent="${entity.parentId||''}" ${mission.skills.includes(entity.id)?'checked':''}><button type="button" class="inline-icon description-trigger" data-entity-description="${entity.id}" aria-label="Show description for ${esc(entity.title)}">${iconSvg(entity.icon)||esc(entity.icon)}</button><span class="xp-choice-name">${esc(entity.title)}<small>${entity.parentId?'SKILL / 45% XP':'ATTRIBUTE / FULL XP'}</small></span><span class="skill-lock" aria-hidden="true">◇</span></label>`;}
function bindSkillAssignments(){bindAssignmentDescriptions();const choices=$$('[name=skills]'),parents=choices.filter(i=>!i.dataset.attributeParent);for(const parent of parents){const children=choices.filter(i=>i.dataset.attributeParent===parent.value);if(children.some(c=>c.checked))parent.checked=true;const update=()=>{for(const child of children){child.disabled=!parent.checked;if(child.disabled)child.checked=false;child.closest('label').classList.toggle('locked',child.disabled);child.setAttribute('aria-disabled',String(child.disabled));}};parent.addEventListener('change',update);update();}}

function updateBattery(){if(native&&Date.now()-batteryReadAt>15000){batteryReadAt=Date.now();try{const info=JSON.parse(window.DaemonNative.getBatteryState());if(Number.isFinite(info.percent)&&info.percent>=0&&info.percent<=100)batteryInfo=info;}catch{}}
 $$('.battery-status').forEach(el=>{el.hidden=!batteryInfo;if(!batteryInfo)return;const percent=Math.round(batteryInfo.percent),charging=!!batteryInfo.charging;el.classList.toggle('low',percent<=20&&!charging);el.setAttribute('aria-label',`Battery ${percent}%${charging?', charging':''}`);el.innerHTML=`<span class="battery-shell" aria-hidden="true"><i style="width:${percent}%"></i></span><span>${charging?'ϟ ':''}${percent}%</span>`;});}
if(!native&&navigator.getBattery)navigator.getBattery().then(b=>{const refresh=()=>{batteryInfo={percent:b.level*100,charging:b.charging};updateBattery();};refresh();b.addEventListener('levelchange',refresh);b.addEventListener('chargingchange',refresh);}).catch(()=>{});

function bindAssignmentDescriptions(){
 const modal=$('#editor');
 modal.querySelectorAll('[data-entity-description]').forEach(button=>{let timer,x,y;const cancel=()=>clearTimeout(timer);const show=()=>showAssignmentDescription(button);button.addEventListener('pointerdown',e=>{if(e.button!==0)return;x=e.clientX;y=e.clientY;timer=setTimeout(show,450);});button.addEventListener('pointermove',e=>{if(Math.hypot(e.clientX-x,e.clientY-y)>10)cancel();});for(const type of ['pointerup','pointercancel','pointerleave'])button.addEventListener(type,cancel);button.onclick=e=>{e.preventDefault();e.stopPropagation();cancel();if(!modal.querySelector('.description-popup'))show();};button.oncontextmenu=e=>{e.preventDefault();cancel();show();};});
}
function showAssignmentDescription(trigger){
 const modal=$('#editor'),entity=state.skills.find(e=>e.id===trigger.dataset.entityDescription);if(!entity||!modal.open)return;
 modal._closeDescription?.();const popup=document.createElement('section');popup.className='description-popup';popup.setAttribute('role','dialog');popup.setAttribute('aria-labelledby','assignment-description-title');popup.innerHTML=`<div class="panel-title"><div><span class="eyebrow">${entity.parentId?'SKILL':'ATTRIBUTE'}</span><h3 id="assignment-description-title">${esc(entity.title)}</h3></div><button class="close" type="button" aria-label="Close description">×</button></div><p class="assignment-description">${esc(entity.description?.trim()||'No description added yet.')}</p>`;
 const outside=e=>{if(!popup.contains(e.target)&&!trigger.contains(e.target))close(false);},close=(restore=true)=>{popup.remove();modal.removeEventListener('pointerdown',outside);modal.removeEventListener('close',onModalClose);modal._closeDescription=null;if(restore&&trigger.isConnected)trigger.focus({preventScroll:true});},onModalClose=()=>close(false);
 modal._closeDescription=()=>close(false);popup.querySelector('button').onclick=()=>close();popup.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}};modal.append(popup);modal.addEventListener('pointerdown',outside);modal.addEventListener('close',onModalClose,{once:true});popup.querySelector('button').focus({preventScroll:true});
}

function showCompletionAudit(){const modal=$('#editor'),events=state.history.filter(h=>h.type==='complete').slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));modal.className='';modal.innerHTML=`<div class="modal-heading"><h2>Completion audit log</h2><button class="close" data-close aria-label="Close">×</button></div><p>${events.length} recorded completions. Kept after quest cleanup and XP resets.</p>${events.map(h=>`<div class="history-row"><span>✓</span><div><b>${esc(h.title)}</b><small>${esc(new Date(h.at).toLocaleString())}</small></div><div>${h.xp||0} XP<small>${h.coins||0} €$</small></div></div>`).join('')||'<p>No completed missions yet.</p>'}`;modal.querySelector('[data-close]').onclick=()=>modal.close();if(!modal.open)modal.showModal();}
function confirmXPReset(){const modal=$('#editor');modal.className='';modal.innerHTML=`<form id="reset-xp-form"><div class="modal-heading"><h2>Reset experience?</h2><button type="button" class="close" data-close aria-label="Close">×</button></div><p>This sets character XP and every Attribute and Skill’s XP to 0. The character returns to level 1. Credits, quests, and completion history are kept.</p><label class="field">Type CONFIRM to reset<input name="confirmation" autocomplete="off" spellcheck="false" required></label><p id="editor-error" class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="danger" type="submit" disabled>Reset XP</button></div></form>`;const input=modal.querySelector('input'),button=modal.querySelector('[type=submit]');input.oninput=()=>button.disabled=input.value!=='CONFIRM';modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close());modal.querySelector('form').onsubmit=e=>{e.preventDefault();if(input.value!=='CONFIRM')return;if(mutate(()=>{state.profile.xp=0;state.skills.forEach(s=>s.xp=0);})){modal.close();render();toast('Experience reset.');}};if(!modal.open)modal.showModal();input.focus();}

function alertSoundControl(type,sound,mission=false){const key=mission?(type==='alarm'?'missionAlarmSound':'missionNotificationSound'):type;return `<div class="alert-sound-control" data-sound-key="${key}"><input type="hidden" ${mission?'name="'+key+'"':''} value="${esc(JSON.stringify(sound||emptySound()))}"><b>${type==='alarm'?'Alarm':'Notification'} sound</b><p data-sound-name>${esc(sound?.name||(mission?'Use global default':'Android system default'))}</p><div class="heading-actions"><button type="button" class="secondary" data-pick-alert="${type}" ${!native?'disabled':''}>Android sounds</button><button type="button" class="secondary" data-upload-alert="${type}" ${!native?'disabled':''}>Upload audio</button><button type="button" class="text-button" data-reset-alert>Use default</button></div></div>`;}
function alertSettings(){const a=state.settings.alerts;return `<section class="panel alert-settings"><h2>Reminders & alarm audio</h2><p>Reminders and deadlines are notifications by default. Enable Alarm individually in a mission to ring instead.</p>${alertSoundControl('notification',a.notification)}${alertSoundControl('alarm',a.alarm)}<label class="setting">Volume buttons dismiss ringing alarms<input id="volume-dismiss" type="checkbox" ${a.volumeDismiss?'checked':''}></label><p class="fine-print">Works on the alarm screen, including over the lock screen when Android permits it. Buttons cannot be intercepted globally when Android keeps that screen in the background. Notification channels, Do Not Disturb, system volume and full-screen access remain controlled by Android. Imported audio references are device-local; reselect files after moving a backup to another phone.</p>${native?'<button class="secondary" data-alarm-access>Android alarm-screen access</button>':'<p class="muted">Android sound selection and ringing alarms require the APK. Web notifications use browser-controlled audio.</p>'}</section>`;}
function missionAlertFields(x){const a=x.alerts||{alarms:[],dueAlarm:false,notification:emptySound(),alarm:emptySound()};return `<section class="editor-section" data-mission-alerts><h3>Reminder delivery & audio</h3><p class="fine-print">Unchecked reminders use notifications. Toggle Alarm to ring for that reminder only.</p><div data-reminder-types></div><label class="setting">Deadline alert / Alarm<input type="checkbox" name="dueAlarm" ${a.dueAlarm?'checked':''}></label><fieldset data-audio-type="notification">${alertSoundControl('notification',a.notification,true)}</fieldset><fieldset data-audio-type="alarm">${alertSoundControl('alarm',a.alarm,true)}</fieldset></section>`;}
function bindMissionAlerts(x){let flags=[...(x.alerts?.alarms||[])];const section=$('[data-mission-alerts]'),refresh=()=>{const repeatable=$('[name=repeatable]')?.checked,count=repeatable?0:+$('[name=reminderCount]').value;flags=$$('[name=alertAlarm]').length?$$('[name=alertAlarm]').map(i=>i.checked):flags;section.querySelector('[data-reminder-types]').innerHTML=Array.from({length:count},(_,i)=>`<label class="setting">Pre-reminder ${i+1} / Alarm<input type="checkbox" name="alertAlarm" ${flags[i]?'checked':''}></label>`).join('');const due=$('[name=dueAlarm]');due.disabled=!!repeatable;const alarmCount=$$('[name=alertAlarm]:checked').length+(due.checked?1:0),total=count+1;for(const type of ['alarm','notification']){const f=section.querySelector('[data-audio-type="'+type+'"]'),enabled=!repeatable&&(type==='alarm'?alarmCount>0:alarmCount<total);f.disabled=!enabled;f.classList.toggle('disabled',!enabled);}section.querySelectorAll('[name=alertAlarm]').forEach(i=>i.onchange=refresh);};for(const name of ['reminderCount','repeatable','dueAlarm'])$('[name='+name+']')?.addEventListener('change',refresh);refresh();wireAlertSounds(section,true);}

function wireAlertSounds(root,mission=false){root.querySelectorAll('[data-sound-key]').forEach(control=>{const hidden=control.querySelector('input'),type=control.dataset.soundKey.toLowerCase().includes('alarm')?'alarm':'notification',save=sound=>{if(mission){if(!control.isConnected)return;hidden.value=JSON.stringify(sound);control.querySelector('[data-sound-name]').textContent=sound.name||'Use global default';}else if(mutate(()=>state.settings.alerts[type]=sound))render();};control.querySelector('[data-reset-alert]').onclick=()=>save(emptySound());for(const [attr,upload] of [['data-pick-alert',false],['data-upload-alert',true]])control.querySelector('['+attr+']').onclick=()=>{pendingAlertSound={save,control};window.DaemonNative.pickAlertSound(type,upload);};});}
window.daemonAlertSoundPicked=sound=>{const pending=pendingAlertSound;pendingAlertSound=null;if(pending?.control.isConnected&&sound&&typeof sound.uri==='string'&&sound.uri.startsWith('content://'))pending.save(sound);};
function bindAlertSettings(){const root=$('.alert-settings');if(!root)return;wireAlertSounds(root);$('#volume-dismiss').onchange=e=>mutate(()=>state.settings.alerts.volumeDismiss=e.target.checked);$('[data-alarm-access]')?.addEventListener('click',()=>window.DaemonNative.alarmScreenAccess());}

function attentionSettings(){const a=state.settings.attention;return `<section class="panel attention-settings"><h2>Focus & feedback</h2><label class="setting">Calmer interface<input id="focus-mode" type="checkbox" ${a.focus?'checked':''}></label><p class="muted">Less background movement, clearer quest cards, and quieter visual decoration.</p><label class="setting">Reduced reward motion<input id="reduce-motion" type="checkbox" ${a.reducedMotion?'checked':''}></label><p class="muted">Show a short static reward summary. Your device’s reduced-motion preference is also respected. Reward sounds can be muted separately.</p></section>`;}
