function setupCharacterStudio(){const modal=$('#editor');modal.classList.add('character-studio');const form=$('#item-form'),header=form.querySelector('.modal-heading'),preview=$('#character-preview'),footer=form.querySelector('.modal-actions'),error=$('#editor-error');header.querySelector('h2').textContent='Character studio 2.0';const groups=[['identity','Identity'],['face','Face'],['hair','Hair & body'],['outfit','Outfit & gear'],['image','Image & size']],panels=Object.fromEntries(groups.map(([id])=>{const el=document.createElement('section');el.dataset.studioPanel=id;el.hidden=id!=='identity';return [id,el];}));for(const node of [...form.children]){if([header,preview,footer,error].includes(node))continue;let group='identity';if(node.querySelector('[name=hair]'))group='hair';else if(node.querySelector('[name=eyeStyle]'))group='face';else if(node.querySelector('[name=clothes]')||node.id==='palette-fields')group='outfit';else if(node.querySelector('[name=scale],[name=image],[name=removeImage]')||node.matches('.image-preview,.fine-print'))group='image';panels[group].append(node);}const tabs=document.createElement('nav');tabs.className='studio-tabs';tabs.setAttribute('aria-label','Character studio sections');tabs.innerHTML=groups.map(([id,title])=>`<button type="button" data-studio-tab="${id}" aria-pressed="${id==='identity'}">${title}</button>`).join('');header.after(preview,tabs,...Object.values(panels));form.append(error,footer);tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{for(const [id,panel] of Object.entries(panels))panel.hidden=id!==b.dataset.studioTab;tabs.querySelectorAll('button').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));});for(const [name,names] of [['hair',hairNames],['clothes',clothesNames],['accessory',itemNames],['faceType',faceNames]]){const input=$('[name='+name+']'),gallery=document.createElement('div');gallery.className='studio-gallery';gallery.innerHTML=names.map((label,i)=>`<button type="button" data-character-pick="${name}" data-value="${i}" aria-pressed="${+input.value===i}" aria-label="${esc(label)}">${sprite({...characterDraft,[name]:i})}<small>${esc(label)}</small></button>`).join('');input.closest('label').after(gallery);gallery.querySelectorAll('button').forEach(b=>b.onclick=()=>{input.value=b.dataset.value;input.dispatchEvent(new Event('input',{bubbles:true}));});}}
